export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // CORS 预检支持
    if (request.method === 'OPTIONS') {
      return new Response(null, {
        headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type',
        },
      });
    }

    // ========================================================================
    // 路由 1：PWA Manifest (/manifest.json)
    // ========================================================================
    if (url.pathname === '/manifest.json' || url.pathname === '/manifest.webmanifest') {
      return new Response(MANIFEST_JSON, {
        headers: {
          'Content-Type': 'application/manifest+json; charset=UTF-8',
          'Cache-Control': 'public, max-age=86400',
          'X-Content-Type-Options': 'nosniff',
        },
      });
    }

    // ========================================================================
    // 路由 2：PWA Service Worker (/sw.js)
    // ========================================================================
    if (url.pathname === '/sw.js') {
      return new Response(SERVICE_WORKER_JS, {
        headers: {
          'Content-Type': 'application/javascript; charset=UTF-8',
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          'Service-Worker-Allowed': '/',
          'X-Content-Type-Options': 'nosniff',
        },
      });
    }

    // ========================================================================
    // 路由 3：高清 App 图标 (/icon.svg)
    // ========================================================================
    if (url.pathname === '/icon.svg') {
      return new Response(ICON_SVG, {
        headers: {
          'Content-Type': 'image/svg+xml; charset=UTF-8',
          'Cache-Control': 'public, max-age=604800',
        },
      });
    }

    // ========================================================================
    // 路由 4：KV 云端状态读写 API (/api/state?space=xxx)
    // ========================================================================
    if (url.pathname === '/api/state') {
      const rawSpace = (url.searchParams.get('space') || 'default').trim().toLowerCase();
      const spaceId = /^[a-z0-9_-]{1,24}$/.test(rawSpace) ? rawSpace : 'default';
      const kvKey = `STARLIGHT_SPACE_V3_${spaceId}`;

      const kvStore = env.STARLIGHT_KV || env.KV || env.starlight_kv || env.kv || env.STARLIGHT || env.STORAGE;
      if (!kvStore) {
        return jsonResponse({
          ok: false,
          kvBound: false,
          message: '未检测到 STARLIGHT_KV 绑定，当前仅使用浏览器本地存储'
        }, 200);
      }

      if (request.method === 'GET') {
        try {
          const data = await kvStore.get(kvKey, { type: 'json' });
          return jsonResponse({
            ok: true,
            kvBound: true,
            space: spaceId,
            data: data || null
          });
        } catch (err) {
          return jsonResponse({ ok: false, error: err.message }, 500);
        }
      }

      if (request.method === 'POST') {
        try {
          // 限制单次 Payload 大小（最大 512KB）
          const contentLength = parseInt(request.headers.get('content-length') || '0', 10);
          if (contentLength > 524288) {
            return jsonResponse({ ok: false, error: 'Payload too large (max 512KB)' }, 413);
          }

          const body = await request.json();
          if (!body || typeof body !== 'object') {
            return jsonResponse({ ok: false, error: 'Invalid payload' }, 400);
          }
          body.updatedAt = Date.now();
          await kvStore.put(kvKey, JSON.stringify(body));
          return jsonResponse({
            ok: true,
            kvBound: true,
            space: spaceId,
            updatedAt: body.updatedAt
          });
        } catch (err) {
          return jsonResponse({ ok: false, error: err.message }, 500);
        }
      }
    }

    // ========================================================================
    // 路由 5：返回内嵌完整前端单页 HTML
    // ========================================================================
    return new Response(HTML_PAGE, {
      headers: {
        'Content-Type': 'text/html; charset=UTF-8',
        'Cache-Control': 'no-cache',
        'X-Content-Type-Options': 'nosniff',
        'X-Frame-Options': 'SAMEORIGIN',
      },
    });
  },
};

function jsonResponse(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=UTF-8',
      'Cache-Control': 'no-store',
      'Access-Control-Allow-Origin': '*',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}

const MANIFEST_JSON = '{\n  "name": "星光少女成长打卡站",\n  "short_name": "星光打卡",\n  "description": "每日习惯任务打卡、早鸟工整加成与积分商城",\n  "start_url": "/",\n  "scope": "/",\n  "display": "standalone",\n  "orientation": "portrait",\n  "background_color": "#0f172a",\n  "theme_color": "#6366f1",\n  "icons": [\n    {\n      "src": "/icon.svg",\n      "sizes": "any",\n      "type": "image/svg+xml",\n      "purpose": "any maskable"\n    }\n  ]\n}';

const SERVICE_WORKER_JS = "const CACHE_NAME = 'starlight-pwa-v2';\nconst STATIC_ASSETS = [\n  '/',\n  '/manifest.json',\n  '/icon.svg'\n];\n\nself.addEventListener('install', (event) => {\n  event.waitUntil(\n    caches.open(CACHE_NAME).then((cache) => cache.addAll(STATIC_ASSETS)).then(() => self.skipWaiting())\n  );\n});\n\nself.addEventListener('activate', (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => {\n      return Promise.all(\n        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))\n      );\n    }).then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener('fetch', (event) => {\n  const url = new URL(event.request.url);\n\n  // 1. KV API 请求：Network-first，断网返回离线标记\n  if (url.pathname.startsWith('/api/')) {\n    event.respondWith(\n      fetch(event.request).catch(() => {\n        return new Response(JSON.stringify({ ok: false, offline: true, message: '离线模式' }), {\n          headers: { 'Content-Type': 'application/json' },\n        });\n      })\n    );\n    return;\n  }\n\n  // 2. 静态页面与 CDN 资源：Stale-While-Revalidate + Cache fallback\n  event.respondWith(\n    caches.match(event.request).then((cachedResponse) => {\n      const fetchPromise = fetch(event.request).then((networkResponse) => {\n        if (networkResponse && (networkResponse.status === 200 || networkResponse.type === 'opaque')) {\n          const resClone = networkResponse.clone();\n          caches.open(CACHE_NAME).then((cache) => cache.put(event.request, resClone));\n        }\n        return networkResponse;\n      }).catch(() => null);\n\n      if (cachedResponse) {\n        return cachedResponse;\n      }\n\n      return fetchPromise.then((networkResponse) => {\n        if (networkResponse) return networkResponse;\n        return caches.match('/');\n      });\n    })\n  );\n});\n";

const ICON_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">\n  <defs>\n    <!-- 深邃梦幻夜空渐变 -->\n    <linearGradient id="nightSky" x1="0%" y1="0%" x2="100%" y2="100%">\n      <stop offset="0%" stop-color="#080C1B" />\n      <stop offset="35%" stop-color="#111638" />\n      <stop offset="70%" stop-color="#1E1B4B" />\n      <stop offset="100%" stop-color="#311042" />\n    </linearGradient>\n\n    <!-- 柔金月牙渐变 -->\n    <linearGradient id="moonGlowGrad" x1="20%" y1="10%" x2="90%" y2="100%">\n      <stop offset="0%" stop-color="#FFFBEB" />\n      <stop offset="30%" stop-color="#FEF08A" />\n      <stop offset="75%" stop-color="#FBBF24" />\n      <stop offset="100%" stop-color="#F59E0B" />\n    </linearGradient>\n\n    <!-- 星芒柔白渐变 -->\n    <linearGradient id="starLightGrad" x1="0%" y1="0%" x2="100%" y2="100%">\n      <stop offset="0%" stop-color="#FFFFFF" />\n      <stop offset="60%" stop-color="#FDE047" />\n      <stop offset="100%" stop-color="#F59E0B" />\n    </linearGradient>\n\n    <!-- 梦幻星云光晕渐变 -->\n    <radialGradient id="nebulaGlow" cx="50%" cy="45%" r="60%">\n      <stop offset="0%" stop-color="#818CF8" stop-opacity="0.35" />\n      <stop offset="50%" stop-color="#C084FC" stop-opacity="0.15" />\n      <stop offset="100%" stop-color="#1E1B4B" stop-opacity="0" />\n    </radialGradient>\n\n    <!-- 柔和发光滤镜 -->\n    <filter id="glowFilter" x="-30%" y="-30%" width="160%" height="160%">\n      <feGaussianBlur stdDeviation="10" result="blur1" />\n      <feGaussianBlur stdDeviation="20" result="blur2" />\n      <feMerge>\n        <feMergeNode in="blur2" />\n        <feMergeNode in="blur1" />\n        <feMergeNode in="SourceGraphic" />\n      </feMerge>\n    </filter>\n\n    <!-- 微星点滤镜 -->\n    <filter id="starGlow" x="-50%" y="-50%" width="200%" height="200%">\n      <feGaussianBlur stdDeviation="3" result="blur" />\n      <feMerge>\n        <feMergeNode in="blur" />\n        <feMergeNode in="SourceGraphic" />\n      </feMerge>\n    </filter>\n  </defs>\n\n  <!-- 1. 圆角应用底座（符合 Apple iOS 与 Android Maskable 图标规范） -->\n  <rect width="512" height="512" rx="118" fill="url(#nightSky)" />\n\n  <!-- 2. 星云扩散光晕 -->\n  <circle cx="260" cy="240" r="230" fill="url(#nebulaGlow)" />\n\n  <!-- 3. 背景璀璨微星群 -->\n  <g opacity="0.85">\n    <circle cx="90" cy="110" r="2" fill="#FFFFFF" opacity="0.6" />\n    <circle cx="140" cy="80" r="3" fill="#FDE047" opacity="0.75" filter="url(#starGlow)" />\n    <circle cx="220" cy="65" r="1.8" fill="#FFFFFF" opacity="0.5" />\n    <circle cx="370" cy="85" r="2.5" fill="#FDE047" opacity="0.7" />\n    <circle cx="435" cy="130" r="2" fill="#FFFFFF" opacity="0.6" />\n    <circle cx="440" cy="280" r="3" fill="#C084FC" opacity="0.8" filter="url(#starGlow)" />\n    <circle cx="400" cy="390" r="2.2" fill="#FFFFFF" opacity="0.55" />\n    <circle cx="105" cy="380" r="2" fill="#FDE047" opacity="0.6" />\n    <circle cx="80" cy="260" r="2.5" fill="#C084FC" opacity="0.7" />\n    <circle cx="165" cy="440" r="1.8" fill="#FFFFFF" opacity="0.45" />\n    <circle cx="320" cy="445" r="2.2" fill="#FDE047" opacity="0.75" />\n  </g>\n\n  <!-- 4. 梦幻星轨弧线 -->\n  <path d="M 80 340 C 140 430, 360 450, 440 310" stroke="#818CF8" stroke-width="1.5" stroke-dasharray="4 8" opacity="0.35" fill="none" />\n  <path d="M 100 200 C 170 120, 340 110, 420 180" stroke="#C084FC" stroke-width="1.2" stroke-dasharray="3 7" opacity="0.28" fill="none" />\n\n  <!-- 5. 主角：皎洁温润的月牙（采用几何布尔差集造型） -->\n  <path d="M 285 105\n           C 185 105, 110 185, 110 285\n           C 110 375, 175 448, 260 460\n           C 180 435, 145 340, 160 255\n           C 175 180, 230 125, 285 105 Z"\n        fill="url(#moonGlowGrad)"\n        filter="url(#glowFilter)" />\n\n  <!-- 6. 月弯怀抱中的守护四角主星 -->\n  <g transform="translate(330, 225)" filter="url(#glowFilter)">\n    <!-- 主星辉光四角星芒 -->\n    <path d="M 0 -48 Q 0 0, -48 0 Q 0 0, 0 48 Q 0 0, 48 0 Q 0 0, 0 -48 Z" fill="url(#starLightGrad)" />\n    <!-- 核心微星光核 -->\n    <circle cx="0" cy="0" r="9" fill="#FFFFFF" />\n  </g>\n\n  <!-- 7. 伴星一（右上轻盈四角小星） -->\n  <g transform="translate(395, 150) scale(0.48)" filter="url(#starGlow)">\n    <path d="M 0 -42 Q 0 0, -42 0 Q 0 0, 0 42 Q 0 0, 42 0 Q 0 0, 0 -42 Z" fill="#FFFFFF" />\n  </g>\n\n  <!-- 8. 伴星二（左下灵动四角小星） -->\n  <g transform="translate(195, 375) scale(0.38)" filter="url(#starGlow)">\n    <path d="M 0 -42 Q 0 0, -42 0 Q 0 0, 0 42 Q 0 0, 42 0 Q 0 0, 0 -42 Z" fill="#FEF08A" />\n  </g>\n\n  <!-- 9. 伴星三（右下晶莹星点） -->\n  <g transform="translate(365, 335) scale(0.32)" filter="url(#starGlow)">\n    <path d="M 0 -42 Q 0 0, -42 0 Q 0 0, 0 42 Q 0 0, 42 0 Q 0 0, 0 -42 Z" fill="#FFFFFF" />\n  </g>\n\n  <!-- 10. 柔和星光光斑（点睛高光） -->\n  <circle cx="240" cy="200" r="3.5" fill="#FFFFFF" opacity="0.9" filter="url(#starGlow)" />\n  <circle cx="275" cy="310" r="2.5" fill="#FDE047" opacity="0.85" />\n  <circle cx="315" cy="160" r="3" fill="#FFFFFF" opacity="0.75" />\n</svg>';

const HTML_PAGE = '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">\n    <meta name="apple-mobile-web-app-capable" content="yes">\n    <meta name="apple-mobile-web-app-status-bar-style" content="default">\n    <title>星光少女成长打卡站 · 每日任务与积分核算</title>\n    <link rel=manifest href=/manifest.json>\n    <meta name=theme-color content=#6366f1>\n    <link rel=icon type=image/svg+xml href=/icon.svg>\n    <link rel=apple-touch-icon href=/icon.svg>\n    <meta name=apple-mobile-web-app-title content=星光打卡>\n    <script src="https://cdn.tailwindcss.com"></script>\n\n    <script>\n        tailwind.config = {\n            theme: {\n                extend: {\n                    fontFamily: {\n                        sans: [\n                            \'ui-rounded\',\n                            \'"SF Pro Rounded"\',\n                            \'"PingFang SC"\',\n                            \'"Hiragino Sans GB"\',\n                            \'"Microsoft YaHei UI"\',\n                            \'"Microsoft YaHei"\',\n                            \'"Noto Sans SC"\',\n                            \'system-ui\',\n                            \'-apple-system\',\n                            \'sans-serif\'\n                        ],\n                        numeric: [\n                            \'ui-rounded\',\n                            \'"SF Pro Rounded"\',\n                            \'system-ui\',\n                            \'-apple-system\',\n                            \'"PingFang SC"\',\n                            \'sans-serif\'\n                        ],\n                    },\n                    colors: {\n                        pastel: {\n                            bg: \'#FAF8FF\',\n                            surface: \'#F5F3FF\',\n                            lavender: \'#8B7CF6\',\n                            lavenderLight: \'#EDE9FE\',\n                            lavenderDark: \'#6D28D9\',\n                            mint: \'#34D399\',\n                            mintLight: \'#ECFDF5\',\n                            sakura: \'#F472B6\',\n                            sakuraLight: \'#FDF2F8\',\n                            sky: \'#38BDF8\',\n                            skyLight: \'#F0F9FF\',\n                            butter: \'#FBBF24\',\n                            butterLight: \'#FFFBEB\',\n                        }\n                    },\n                    boxShadow: {\n                        \'pastel\': \'0 10px 30px -5px rgba(139, 124, 246, 0.12), 0 4px 12px -2px rgba(139, 124, 246, 0.06)\',\n                        \'pastel-sm\': \'0 4px 16px -2px rgba(139, 124, 246, 0.10)\',\n                        \'pastel-mint\': \'0 8px 24px -4px rgba(52, 211, 153, 0.18)\',\n                        \'pastel-butter\': \'0 8px 24px -4px rgba(251, 191, 36, 0.18)\',\n                        \'jelly\': \'0 6px 0 0 #7C3AED\',\n                        \'jelly-mint\': \'0 6px 0 0 #10B981\',\n                    }\n                }\n            }\n        }\n    </script>\n\n    <style>\n        html, body {\n            margin: 0;\n            padding: 0;\n        }\n        :root {\n            --theme-bg: #FAF8FF;\n            --theme-dot: #E5DEFF;\n            --theme-primary: #8B7CF6;\n            --theme-primary-dark: #7C3AED;\n            --theme-shadow: rgba(139, 124, 246, 0.14);\n            --theme-border: #EDE9FE;\n            --theme-jelly: #6D28D9;\n        }\n        body.theme-boy {\n            --theme-bg: #F4F9FF;\n            --theme-dot: #CFE5FF;\n            --theme-primary: #3B82F6;\n            --theme-primary-dark: #2563EB;\n            --theme-shadow: rgba(59, 130, 246, 0.14);\n            --theme-border: #DBEAFE;\n            --theme-jelly: #1D4ED8;\n        }\n        body {\n            font-family: ui-rounded, \'SF Pro Rounded\', \'PingFang SC\', \'Hiragino Sans GB\', \'Microsoft YaHei UI\', \'Microsoft YaHei\', \'Noto Sans SC\', system-ui, -apple-system, sans-serif;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n            text-rendering: optimizeLegibility;\n            background-color: var(--theme-bg);\n            background-image: \n                radial-gradient(at 12% 10%, rgba(237, 233, 254, 0.85) 0px, transparent 50%),\n                radial-gradient(at 88% 15%, rgba(253, 242, 248, 0.8) 0px, transparent 45%),\n                radial-gradient(at 85% 85%, rgba(236, 253, 245, 0.75) 0px, transparent 50%),\n                radial-gradient(at 15% 80%, rgba(255, 251, 235, 0.75) 0px, transparent 45%),\n                radial-gradient(var(--theme-dot) 1.25px, transparent 1.25px);\n            background-size: 100% 100%, 100% 100%, 100% 100%, 100% 100%, 28px 28px;\n            color: #3B3355;\n            -webkit-tap-highlight-color: transparent;\n            transition: background-color 0.35s ease;\n        }\n\n        /* 游戏化等宽与平稳数值排版，消除 CountUp 滚动抖动 */\n        .font-numeric,\n        .tabular-nums,\n        #stat-wallet,\n        #stat-pending,\n        #level-xp-text,\n        #must-progress-text,\n        #must-progress-pct,\n        #modal-total-score {\n            font-variant-numeric: tabular-nums;\n            font-feature-settings: "tnum";\n            letter-spacing: -0.015em;\n        }\n        body.theme-boy {\n            background-image: \n                radial-gradient(at 12% 10%, rgba(219, 234, 254, 0.9) 0px, transparent 50%),\n                radial-gradient(at 88% 15%, rgba(207, 250, 254, 0.8) 0px, transparent 45%),\n                radial-gradient(at 85% 85%, rgba(236, 253, 245, 0.75) 0px, transparent 50%),\n                radial-gradient(at 15% 80%, rgba(254, 249, 195, 0.65) 0px, transparent 45%),\n                radial-gradient(var(--theme-dot) 1.25px, transparent 1.25px);\n            color: #1E293B;\n        }\n        body.theme-boy #hero-card {\n            border-color: rgba(219, 234, 254, 0.95);\n            box-shadow: 0 12px 36px -6px rgba(59, 130, 246, 0.15), 0 4px 12px rgba(0, 0, 0, 0.03);\n        }\n        body.theme-boy #hero-blob-1 {\n            background-image: linear-gradient(to bottom right, rgba(191, 219, 254, 0.6), rgba(207, 250, 254, 0.45), transparent);\n        }\n        body.theme-boy #hero-top-divider {\n            border-color: rgba(219, 234, 254, 0.85);\n        }\n        body.theme-boy #theme-avatar-box {\n            --tw-ring-color: rgba(191, 219, 254, 0.8);\n        }\n        body.theme-boy #sound-btn,\n        body.theme-boy #settings-top-btn {\n            background-color: rgba(239, 246, 255, 0.9);\n            color: #1D4ED8;\n            border-color: rgba(191, 219, 254, 0.85);\n        }\n        body.theme-boy #sound-btn:hover,\n        body.theme-boy #settings-top-btn:hover {\n            background-color: #DBEAFE;\n        }\n        body.theme-boy #level-capsule {\n            background-color: rgba(239, 246, 255, 0.95);\n            border-color: rgba(191, 219, 254, 0.9);\n        }\n        body.theme-boy #level-badge {\n            color: #1D4ED8;\n        }\n        body.theme-boy #level-progress-bg {\n            background-color: rgba(191, 219, 254, 0.7);\n        }\n        body.theme-boy #level-progress-bar {\n            background-image: linear-gradient(to right, #3B82F6, #06B6D4);\n        }\n        body.theme-boy #level-xp-text {\n            color: #2563EB;\n        }\n        body.theme-boy #nav-pill-container {\n            border-color: #DBEAFE;\n        }\n        body.theme-boy #tab-btn-shop:hover,\n        body.theme-boy #tab-btn-history:hover,\n        body.theme-boy #tab-btn-tasks:hover {\n            background-color: #EFF6FF;\n        }\n        body.theme-boy #shop-header-box {\n            border-color: #DBEAFE;\n        }\n        body.theme-boy #shop-header-icon {\n            background-color: #EFF6FF;\n            color: #2563EB;\n            border-color: #BFDBFE;\n        }\n        body.theme-boy #btn-manage-rewards {\n            background-color: #EFF6FF;\n            border-color: #BFDBFE;\n            color: #1D4ED8;\n        }\n        body.theme-boy #btn-add-reward {\n            background-color: #ECFEFF;\n            border-color: #A5F3FC;\n            color: #0E7490;\n        }\n        body.theme-boy #history-header-box,\n        body.theme-boy #history-container-box {\n            border-color: #DBEAFE;\n        }\n        body.theme-boy #history-header-icon {\n            background-color: #EFF6FF;\n            color: #2563EB;\n            border-color: #BFDBFE;\n        }\n        body.theme-boy #history-count {\n            background-color: #DBEAFE;\n            color: #1E40AF;\n        }\n        body.theme-boy #btn-history-adjust {\n            background-color: #FFFBEB;\n            border-color: #FDE68A;\n            color: #B45309;\n        }\n        body.theme-boy #btn-history-export,\n        body.theme-boy #btn-history-import {\n            background-color: #EFF6FF;\n            border-color: #BFDBFE;\n            color: #1D4ED8;\n        }\n        body.theme-boy #floating-bottom-bar {\n            border-color: #93C5FD;\n        }\n        body.theme-boy ::-webkit-scrollbar-track {\n            background: #F0F7FF;\n        }\n        body.theme-boy ::-webkit-scrollbar-thumb {\n            background: #BFDBFE;\n        }\n\n        .theme-primary-bg {\n            background: linear-gradient(135deg, var(--theme-primary), var(--theme-primary-dark));\n        }\n        .theme-jelly-btn {\n            background: linear-gradient(135deg, var(--theme-primary), var(--theme-primary-dark));\n            box-shadow: 0 6px 0 0 var(--theme-jelly);\n        }\n        .theme-jelly-btn:active {\n            transform: translateY(3px);\n            box-shadow: 0 2px 0 0 var(--theme-jelly);\n        }\n\n        .card-3d-press, .card-bounce {\n            transition: transform 0.14s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.14s ease;\n            user-select: none;\n            -webkit-user-select: none;\n        }\n        .card-3d-press:hover, .card-bounce:hover {\n            transform: translateY(-2px);\n        }\n        .card-3d-press:active, .card-bounce:active {\n            transform: translateY(3px) scale(0.98);\n        }\n\n        @keyframes checkStroke {\n            0% {\n                stroke-dashoffset: 24;\n                transform: scale(0.7);\n            }\n            65% {\n                transform: scale(1.18);\n            }\n            100% {\n                stroke-dashoffset: 0;\n                transform: scale(1);\n            }\n        }\n        .animate-check-svg {\n            transform-origin: center;\n            animation: checkStroke 0.22s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;\n        }\n        .animate-check-svg polyline {\n            stroke-dasharray: 24;\n            stroke-dashoffset: 0;\n            animation: strokeDraw 0.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;\n        }\n        @keyframes strokeDraw {\n            0% { stroke-dashoffset: 24; }\n            100% { stroke-dashoffset: 0; }\n        }\n\n        .progress-ring-circle {\n            transition: stroke-dashoffset 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);\n            transform: rotate(-90deg);\n            transform-origin: 50% 50%;\n        }\n\n        @keyframes popIn {\n            0% { opacity: 0; transform: scale(0.9) translateY(10px); }\n            100% { opacity: 1; transform: scale(1) translateY(0); }\n        }\n        .animate-pop {\n            animation: popIn 0.25s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;\n        }\n\n        ::-webkit-scrollbar {\n            width: 8px;\n            height: 8px;\n        }\n        ::-webkit-scrollbar-track {\n            background: #F5F3FF;\n            border-radius: 9999px;\n        }\n        ::-webkit-scrollbar-thumb {\n            background: #DDD6FE;\n            border-radius: 9999px;\n        }\n\n        /* 弹窗专用内嵌滚动条，圆角轨道内部缩进，绝不出界 */\n        .custom-modal-scroll {\n            scrollbar-width: thin;\n            scrollbar-color: #FBBF24 #FEF3C7;\n        }\n        .custom-modal-scroll::-webkit-scrollbar {\n            width: 6px;\n        }\n        .custom-modal-scroll::-webkit-scrollbar-track {\n            background: #FEF3C7;\n            border-radius: 9999px;\n            margin: 6px 0;\n        }\n        .custom-modal-scroll::-webkit-scrollbar-thumb {\n            background: #FBBF24;\n            border-radius: 9999px;\n        }\n        .custom-modal-scroll::-webkit-scrollbar-thumb:hover {\n            background: #F59E0B;\n        }\n    </style>\n</head>\n<body class="min-h-screen pb-36 selection:bg-violet-200 selection:text-violet-900">\n\n    <!-- Celebration Confetti Canvas -->\n    <canvas id="confetti-canvas" class="fixed inset-0 pointer-events-none z-50 w-full h-full"></canvas>\n\n    <!-- Toast Container -->\n    <div id="toast-container" class="fixed top-4 right-4 left-4 sm:left-auto z-50 flex flex-col gap-2 items-center sm:items-end pointer-events-none"></div>\n\n    <!-- Top Header & Compact Pastel Dashboard -->\n    <header class="max-w-4xl mx-auto px-4 pt-3 sm:pt-4 pb-1">\n        <div id="hero-card" class="bg-white/95 backdrop-blur-2xl rounded-[30px] px-4 py-4 sm:px-6 sm:py-5 shadow-[0_12px_36px_-6px_rgba(139,92,246,0.12),0_4px_12px_rgba(0,0,0,0.03)] border border-violet-100/90 relative overflow-hidden transition-colors duration-300">\n            <div id="hero-blob-1" class="absolute -top-12 -right-12 w-44 h-44 bg-gradient-to-br from-violet-200/50 via-pink-100/40 to-transparent rounded-full pointer-events-none blur-sm"></div>\n            <div id="hero-blob-2" class="absolute -bottom-14 -left-14 w-40 h-40 bg-gradient-to-tr from-emerald-100/50 via-teal-50/40 to-transparent rounded-full pointer-events-none blur-sm"></div>\n\n            <!-- Top Row: Avatar, Title & Right Action Buttons -->\n            <div id="hero-top-divider" class="relative z-10 flex flex-row items-center justify-between gap-3 pb-3.5 border-b-2 border-dashed border-violet-100/80">\n                <div class="flex items-center gap-3.5 min-w-0">\n                    <div id="theme-avatar-box" onclick="openSettingsModal()" title="点击切换主题或设置" class="cursor-pointer w-12 h-12 sm:w-13 sm:h-13 rounded-[20px] theme-primary-bg flex items-center justify-center text-2xl shadow-pastel-sm border-2 border-white ring-2 ring-violet-200/60 shrink-0 transition-transform hover:scale-105 active:scale-95">\n                        🦄\n                    </div>\n                    <div class="min-w-0">\n                        <h1 id="student-name-display" class="text-base sm:text-xl font-black text-[#2E2545] tracking-tight truncate">星光少女成长打卡站</h1>\n                        <div class="flex items-center gap-2 mt-0.5 flex-wrap">\n                            <p id="current-date-display" class="text-xs text-[#7E7494] font-bold shrink-0"></p>\n                            <span id="theme-subtitle-text" class="hidden md:inline text-[11px] font-bold text-[#8B7CF6] truncate">· 今日事今日毕，每一份努力都闪闪发光 ✨</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Action Buttons: 移除了声音开关，只保留个人空间入口与设置 -->\n                <div class="flex items-center gap-1.5 sm:gap-2 shrink-0">\n                    <button onclick="openShareModal()" id="share-btn" class="px-2.5 sm:px-3 py-1.5 rounded-xl bg-emerald-50/90 hover:bg-emerald-100 text-emerald-700 font-extrabold text-xs transition border border-emerald-200/90 flex items-center gap-1.5 shadow-2xs cursor-pointer active:scale-95" title="切换个人独立空间">\n                        <span id="space-emoji">👧</span>\n                        <span id="space-badge-text" class="inline-block max-w-[84px] sm:max-w-[130px] truncate font-black">个人空间</span>\n                        <span id="space-sync-dot" class="w-2 h-2 rounded-full bg-emerald-500 ring-2 ring-white shrink-0" title="云端KV同步就绪"></span>\n                    </button>\n                    <button onclick="openSettingsModal()" id="settings-top-btn" class="px-2.5 sm:px-3 py-1.5 rounded-xl bg-violet-50/90 hover:bg-violet-100 text-violet-700 font-extrabold text-xs transition border border-violet-200/80 flex items-center gap-1 shadow-2xs cursor-pointer active:scale-95" title="家长设置与风格主题">\n                        <span>⚙️</span>\n                        <span class="hidden sm:inline">设置</span>\n                    </button>\n                </div>\n            </div>\n\n            <!-- Middle Row: 3 Solid 3D Base Pastel Scoreboard Cards -->\n            <div class="relative z-10 grid grid-cols-1 sm:grid-cols-3 gap-2.5 sm:gap-3.5 mt-3.5">\n                <div id="score-card-1" class="bg-gradient-to-br from-[#FAF8FF] to-[#EDE9FE] rounded-[22px] px-4 py-3 border border-violet-200 border-b-4 border-b-violet-300 shadow-sm flex flex-col justify-between gap-2.5 transition-all hover:-translate-y-0.5">\n                    <div class="flex items-center justify-between">\n                        <div>\n                            <span id="score-card-1-label" class="text-[11px] font-extrabold text-violet-600 uppercase tracking-wider block">✨ 当前可用总积分</span>\n                            <div class="flex items-baseline gap-1 mt-0.5">\n                                <span id="stat-wallet" class="text-2xl sm:text-3xl font-black text-violet-900 leading-none">0</span>\n                                <span id="score-card-1-unit" class="text-xs font-bold text-violet-600">分</span>\n                            </div>\n                        </div>\n                        <div id="score-card-1-icon" class="w-11 h-11 rounded-2xl bg-white/90 border border-violet-100 shadow-2xs flex items-center justify-center text-2xl shrink-0">\n                            💎\n                        </div>\n                    </div>\n\n                    <!-- 等级成长进度舱 (方案 A: 由 Header 主标题旁下沉整合至此) -->\n                    <div id="level-capsule-box" class="pt-2 border-t border-dashed border-violet-200/80 flex flex-col gap-1.5">\n                        <div class="flex items-center justify-between text-[10px] font-black">\n                            <span id="level-badge" class="px-2 py-0.5 rounded-md bg-violet-100 text-violet-700">Lv.1</span>\n                            <div class="flex items-center gap-1.5">\n                                <span id="level-xp-text" class="text-violet-600 font-extrabold">0/150 XP</span>\n                                <span id="xp-text" class="text-violet-500/80 font-bold hidden sm:inline">(累计 0 XP)</span>\n                            </div>\n                        </div>\n                        <div id="level-progress-bg" class="w-full h-1.5 bg-violet-200/70 rounded-full overflow-hidden transition-colors">\n                            <div id="level-progress-bar" class="h-full bg-gradient-to-r from-violet-500 to-pink-500 rounded-full transition-all duration-300" style="width: 0%"></div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class="bg-gradient-to-br from-[#FFFDF5] to-[#FEF3C7]/80 rounded-[22px] px-4 py-3 border border-amber-200 border-b-4 border-b-amber-300 shadow-sm flex items-center justify-between transition-all hover:-translate-y-0.5">\n                    <div class="min-w-0">\n                        <span class="text-[11px] font-extrabold text-amber-700 uppercase tracking-wider block">🎁 今日勾选合计</span>\n                        <div class="flex items-baseline gap-1.5 mt-0.5 flex-wrap">\n                            <span id="stat-pending" class="text-2xl sm:text-3xl font-black text-amber-600 leading-none">0</span>\n                            <span class="text-xs font-bold text-amber-700">分</span>\n                            <span id="stat-diff-badge" class="hidden text-[10px] font-extrabold px-1.5 py-0.5 rounded-full bg-white text-emerald-600 border border-emerald-200 shadow-2xs"></span>\n                        </div>\n                        <span id="stat-settled-sub" class="text-[10px] font-bold text-amber-700/80 mt-0.5 block truncate">当日以最后一次提交为准</span>\n                    </div>\n                    <div class="w-11 h-11 rounded-2xl bg-white/90 border border-amber-100 shadow-2xs flex items-center justify-center text-2xl shrink-0">\n                        🧺\n                    </div>\n                </div>\n\n                <div class="bg-gradient-to-br from-[#F0FDF4] to-[#D1FAE5]/70 rounded-[22px] px-4 py-3 border border-emerald-200 border-b-4 border-b-emerald-300 shadow-sm flex items-center justify-between transition-all hover:-translate-y-0.5">\n                    <div>\n                        <span class="text-[11px] font-extrabold text-emerald-700 uppercase tracking-wider block">🌱 今日必做通关</span>\n                        <div class="flex items-baseline gap-1 mt-0.5">\n                            <span id="must-progress-text" class="text-2xl sm:text-3xl font-black text-emerald-700 leading-none">0/7</span>\n                            <span class="text-xs font-bold text-emerald-600">项</span>\n                        </div>\n                        <span id="stat-streak-text" class="text-[10px] font-bold text-emerald-600 mt-0.5 block">🔥 已累计打卡 0 天</span>\n                    </div>\n                    <div class="relative w-12 h-12 shrink-0 flex items-center justify-center bg-white/90 rounded-2xl border border-emerald-100 shadow-2xs">\n                        <svg class="w-10 h-10" viewBox="0 0 56 56">\n                            <circle class="text-emerald-100" stroke-width="5" stroke="currentColor" fill="transparent" r="22" cx="28" cy="28" />\n                            <circle id="must-progress-ring" class="text-emerald-500 progress-ring-circle" stroke-width="5" stroke-dasharray="138.2" stroke-dashoffset="138.2" stroke-linecap="round" stroke="currentColor" fill="transparent" r="22" cx="28" cy="28" />\n                        </svg>\n                        <span id="must-progress-pct" class="absolute text-[10px] font-black text-emerald-800">0%</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </header>\n\n    <!-- Pastel Pill Navigation Tabs -->\n    <div class="max-w-4xl mx-auto px-4 mt-2.5">\n        <div id="nav-pill-container" class="bg-white/85 backdrop-blur-md p-1 rounded-[20px] shadow-pastel-sm border-2 border-violet-100 grid grid-cols-3 gap-1.5">\n            <button onclick="switchTab(\'tasks\')" id="tab-btn-tasks" class="py-2 px-3 rounded-[15px] font-extrabold text-xs sm:text-sm transition-all flex items-center justify-center gap-1.5 theme-primary-bg text-white shadow-sm">\n                <span>📝</span>\n                <span>今日打卡</span>\n            </button>\n            <button onclick="switchTab(\'shop\')" id="tab-btn-shop" class="py-2 px-3 rounded-[15px] font-extrabold text-xs sm:text-sm transition-all flex items-center justify-center gap-1.5 text-[#6E6385] hover:bg-violet-50">\n                <span>🎠</span>\n                <span>积分商城</span>\n            </button>\n            <button onclick="switchTab(\'history\')" id="tab-btn-history" class="py-2 px-3 rounded-[15px] font-extrabold text-xs sm:text-sm transition-all flex items-center justify-center gap-1.5 text-[#6E6385] hover:bg-violet-50">\n                <span>📒</span>\n                <span>成长账本</span>\n            </button>\n        </div>\n    </div>\n\n    <!-- Main Content Container -->\n    <main class="max-w-4xl mx-auto px-4 mt-4 space-y-6 pb-28 sm:pb-32">\n\n        <!-- TAB 1: DAILY CHECK-IN -->\n        <section id="tab-tasks" class="space-y-7">\n            <div id="settled-overwrite-banner" class="hidden bg-gradient-to-r from-emerald-50 via-violet-50 to-pink-50 border-2 border-emerald-200 rounded-[26px] p-4 shadow-pastel-sm flex flex-col sm:flex-row sm:items-center justify-between gap-2">\n                <div class="flex items-center gap-3">\n                    <span class="w-10 h-10 rounded-2xl bg-emerald-400 text-white flex items-center justify-center text-xl shadow-sm shrink-0">✅</span>\n                    <div>\n                        <p id="settled-banner-title" class="text-xs sm:text-sm font-black text-emerald-900">\n                            今日已完成核算入账！但你随时可以继续调整勾选。\n                        </p>\n                        <p class="text-xs font-bold text-[#6E6385] mt-0.5">\n                            💡 规则：当日无论提交多少次，最终积分与账本只以<span class="text-violet-700 underline">当天最后一次提交</span>为准（自动增减差额，不会重复加分）。\n                        </p>\n                    </div>\n                </div>\n                <span id="settled-banner-time" class="text-xs font-extrabold text-violet-700 bg-white px-3 py-1 rounded-full border border-violet-200 shrink-0 self-start sm:self-center"></span>\n            </div>\n\n            <!-- Group 1: 校内基础 -->\n            <div class="space-y-3.5">\n                <div class="flex items-center justify-between px-1 flex-wrap gap-2">\n                    <div class="flex items-center gap-2.5">\n                        <span class="w-9 h-9 rounded-2xl bg-sky-100 text-sky-600 flex items-center justify-center text-lg font-bold border border-sky-200">🏫</span>\n                        <div>\n                            <h2 class="text-base sm:text-lg font-black text-[#2E2545]">每日必做 · 校内基础清零</h2>\n                            <p class="text-xs text-[#7E7494] font-bold">学校布置的语数英基础作业，做完一项勾一项</p>\n                        </div>\n                    </div>\n                    <span id="group-pill-school" class="text-xs font-extrabold text-sky-700 bg-sky-50 border-2 border-sky-200/80 px-3 py-1 rounded-full">\n                        每项 +1 分 · 共 3 分\n                    </span>\n                </div>\n                <div id="grid-school" class="grid grid-cols-1 sm:grid-cols-3 sm:auto-rows-fr gap-4 items-stretch"></div>\n            </div>\n\n            <!-- Group 2: 语数英自学 -->\n            <div class="space-y-3.5">\n                <div class="flex items-center justify-between px-1 flex-wrap gap-2">\n                    <div class="flex items-center gap-2.5">\n                        <span class="w-9 h-9 rounded-2xl bg-violet-100 text-violet-600 flex items-center justify-center text-lg font-bold border border-violet-200">🌱</span>\n                        <div>\n                            <h2 class="text-base sm:text-lg font-black text-[#2E2545]">每日必做 · 语数英额外自学</h2>\n                            <p class="text-xs text-[#7E7494] font-bold">每天一点自主拔高微习惯，积少成多</p>\n                        </div>\n                    </div>\n                    <span id="group-pill-selfstudy" class="text-xs font-extrabold text-violet-700 bg-violet-50 border-2 border-violet-200/80 px-3 py-1 rounded-full">\n                        每项 +2 分 · 共 6 分\n                    </span>\n                </div>\n                <div id="grid-selfstudy" class="grid grid-cols-1 sm:grid-cols-3 sm:auto-rows-fr gap-4 items-stretch"></div>\n            </div>\n\n            <!-- Group 3: 收尾好习惯 -->\n            <div class="space-y-3.5">\n                <div class="flex items-center justify-between px-1 flex-wrap gap-2">\n                    <div class="flex items-center gap-2.5">\n                        <span class="w-9 h-9 rounded-2xl bg-emerald-100 text-emerald-600 flex items-center justify-center text-lg font-bold border border-emerald-200">🧹</span>\n                        <div>\n                            <h2 class="text-base sm:text-lg font-black text-[#2E2545]">每日必做 · 收尾好习惯</h2>\n                            <p class="text-xs text-[#7E7494] font-bold">有始有终，为明天做好清爽准备</p>\n                        </div>\n                    </div>\n                    <span id="group-pill-habit" class="text-xs font-extrabold text-emerald-700 bg-emerald-50 border-2 border-emerald-200/80 px-3 py-1 rounded-full">\n                        必做 +0.5 分\n                    </span>\n                </div>\n                <div id="grid-habit" class="grid grid-cols-1 gap-4"></div>\n            </div>\n\n            <!-- Group 4: 额外悬赏 -->\n            <div class="space-y-3.5 pt-2">\n                <div class="flex items-center justify-between px-1 flex-wrap gap-2">\n                    <div class="flex items-center gap-2.5">\n                        <span class="w-9 h-9 rounded-2xl bg-amber-100 text-amber-600 flex items-center justify-center text-lg font-bold border border-amber-200">🌟</span>\n                        <div>\n                            <h2 class="text-base sm:text-lg font-black text-[#2E2545]">额外悬赏 · 进阶大挑战</h2>\n                            <p class="text-xs text-[#7E7494] font-bold">完成阅读一本书 (+150分) 或学科加练，点击可填写书名/成果备注！</p>\n                        </div>\n                    </div>\n                    <span id="group-pill-bonus" class="text-xs font-extrabold text-amber-800 bg-amber-100 border-2 border-amber-300 px-3 py-1 rounded-full shadow-xs">\n                        🔥 阅读整本书 +150 分\n                    </span>\n                </div>\n                <div id="grid-bonus" class="grid grid-cols-1 sm:grid-cols-2 gap-4"></div>\n            </div>\n        </section>\n\n        <!-- TAB 2: REWARD SHOP -->\n        <section id="tab-shop" class="hidden space-y-5">\n            <div id="shop-header-box" class="bg-white/90 rounded-[26px] p-4 sm:p-5 border-2 border-pink-100 shadow-pastel-sm flex flex-col sm:flex-row sm:items-center justify-between gap-3 transition-colors">\n                <div class="flex items-center gap-3">\n                    <div id="shop-header-icon" class="w-11 h-11 rounded-2xl bg-pink-100 text-pink-600 flex items-center justify-center text-2xl border border-pink-200 shrink-0 transition-colors">🎠</div>\n                    <div>\n                        <h2 class="text-base sm:text-lg font-black text-[#2E2545]">星光心愿兑换商城</h2>\n                        <p class="text-xs font-bold text-[#7E7494]">用每天努力攒下的积分，兑换属于你的自由时间和心愿好礼！</p>\n                    </div>\n                </div>\n                <div class="flex items-center gap-2 flex-wrap shrink-0 self-start sm:self-center">\n                    <button onclick="openManageRewardsModal()" id="btn-manage-rewards" class="px-3.5 py-2 rounded-2xl bg-violet-50 hover:bg-violet-100 text-violet-700 font-extrabold text-xs border-2 border-violet-200 transition">\n                        ✏️ 家长调整既往心愿\n                    </button>\n                    <button onclick="openAddRewardModal()" id="btn-add-reward" class="px-4 py-2 rounded-2xl bg-pink-50 hover:bg-pink-100 text-pink-700 font-extrabold text-xs border-2 border-pink-200 transition">\n                        ➕ 家长上架新心愿\n                    </button>\n                </div>\n            </div>\n\n            <div id="shop-grid" class="grid grid-cols-1 sm:grid-cols-2 gap-4"></div>\n        </section>\n\n        <!-- TAB 3: GROWTH LEDGER -->\n        <section id="tab-history" class="hidden space-y-5">\n            <div id="history-header-box" class="bg-white/90 rounded-[26px] p-4 sm:p-5 border-2 border-violet-100 shadow-pastel-sm flex flex-col sm:flex-row sm:items-center justify-between gap-3 transition-colors">\n                <div class="flex items-center gap-3">\n                    <div id="history-header-icon" class="w-11 h-11 rounded-2xl bg-violet-100 text-violet-600 flex items-center justify-center text-2xl border border-violet-200 shrink-0 transition-colors">📒</div>\n                    <div>\n                        <div class="flex items-center gap-2">\n                            <h2 class="text-base sm:text-lg font-black text-[#2E2545]">星光成长积分账本</h2>\n                            <span id="history-count" class="text-xs font-extrabold px-2.5 py-0.5 rounded-full bg-violet-100 text-violet-700 transition-colors">共 0 条记录</span>\n                        </div>\n                        <p class="text-xs font-bold text-[#7E7494]">记录每一次自律打卡与心愿达成（当日多次提交自动合并为最新一条）</p>\n                    </div>\n                </div>\n                <div class="flex items-center gap-2 flex-wrap">\n                    <button onclick="openManualAdjustModal()" id="btn-history-adjust" class="px-3.5 py-2 rounded-xl bg-amber-50 hover:bg-amber-100 text-amber-800 font-extrabold text-xs border border-amber-200 transition">\n                        ⚡ 家长手动调分\n                    </button>\n                    <button onclick="exportDataJSON()" id="btn-history-export" class="px-3 py-2 rounded-xl bg-violet-50 hover:bg-violet-100 text-violet-700 font-extrabold text-xs border border-violet-200 transition">\n                        📥 备份数据\n                    </button>\n                    <label id="btn-history-import" class="px-3 py-2 rounded-xl bg-violet-50 hover:bg-violet-100 text-violet-700 font-extrabold text-xs border border-violet-200 transition cursor-pointer">\n                        📤 恢复\n                        <input type="file" accept=".json" onchange="importDataJSON(event)" class="hidden">\n                    </label>\n                </div>\n            </div>\n\n            <div id="history-container-box" class="bg-white/95 rounded-[28px] p-4 sm:p-5 border-2 border-violet-100 shadow-pastel-sm transition-colors">\n                <div id="history-list" class="space-y-2.5"></div>\n            </div>\n        </section>\n\n    </main>\n\n    <!-- Floating Bottom Parent Settlement Bar -->\n    <div class="fixed bottom-4 inset-x-0 z-40 px-4 pointer-events-none" style="bottom: max(1rem, env(safe-area-inset-bottom, 1rem));">\n        <div id="floating-bottom-bar" class="max-w-3xl mx-auto bg-white/95 backdrop-blur-xl rounded-[26px] p-3 sm:px-5 sm:py-3.5 border-2 border-violet-200 shadow-pastel flex items-center justify-between gap-3 pointer-events-auto transition-colors">\n            <div class="flex items-center gap-3 min-w-0">\n                <div class="w-10 h-10 rounded-2xl bg-amber-100 text-amber-600 flex items-center justify-center text-xl border border-amber-200 shrink-0">\n                    👑\n                </div>\n                <div class="min-w-0">\n                    <div class="flex items-center gap-2 flex-wrap">\n                        <span id="bottom-bar-summary" class="font-black text-xs sm:text-sm text-[#2E2545] truncate">今日已勾 0 项 · 合计 0 分</span>\n                        <span id="bottom-bar-diff-pill" class="hidden text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 border border-emerald-200"></span>\n                    </div>\n                    <p class="text-[11px] font-bold text-[#7E7494] truncate">当日提交以最后一次为准 · 支持早鸟与工整加成</p>\n                </div>\n            </div>\n\n            <button onclick="openSettlementModal()" class="px-4 sm:px-6 py-2.5 rounded-2xl theme-jelly-btn text-white font-black text-xs sm:text-sm shrink-0 flex items-center gap-1.5 transition cursor-pointer">\n                <span>✨</span>\n                <span id="btn-settle-text">家长最终核算</span>\n            </button>\n        </div>\n    </div>\n\n    <!-- MODAL 1: BONUS CHALLENGE NOTE -->\n    <div id="modal-bonus-note" class="fixed inset-0 z-50 bg-[#2E2545]/45 backdrop-blur-xs hidden items-center justify-center p-4">\n        <div class="bg-white rounded-[32px] max-w-md w-full p-6 border-2 border-amber-200 shadow-pastel animate-pop">\n            <div class="flex items-center justify-between pb-3.5 border-b-2 border-dashed border-amber-100">\n                <div class="flex items-center gap-2.5">\n                    <div id="bonus-modal-icon" class="w-11 h-11 rounded-2xl bg-amber-100 text-amber-600 flex items-center justify-center text-2xl border border-amber-200">\n                        📚\n                    </div>\n                    <div>\n                        <h3 id="bonus-modal-title" class="font-black text-[#2E2545] text-lg">完整阅读一本书</h3>\n                        <p id="bonus-modal-subtitle" class="text-xs font-extrabold text-amber-600">🌟 进阶悬赏挑战 · +150 分</p>\n                    </div>\n                </div>\n                <button onclick="closeModal(\'modal-bonus-note\')" class="w-8 h-8 rounded-full bg-amber-50 text-amber-600 font-bold">✕</button>\n            </div>\n\n            <div class="mt-4">\n                <label id="bonus-modal-label" class="text-xs font-extrabold text-[#5E5475] block mb-2">\n                    📚 写下今天读完的书名或挑战成果吧（选填）：\n                </label>\n                <input type="text" id="bonus-note-input" placeholder="例如：《夏洛的网》/ 奥数行程问题" onkeydown="if(event.key===\'Enter\') confirmBonusTask()" class="w-full px-4 py-3 rounded-2xl border-2 border-amber-200 text-sm font-bold bg-amber-50/40 focus:bg-white focus:outline-none focus:border-amber-400">\n                <p class="text-[11px] font-bold text-[#7E7494] mt-2">\n                    💡 填写后会永久记录在成长账本里，方便爸妈核验表扬！直接点击完成也可以打卡。\n                </p>\n            </div>\n\n            <div class="mt-5 flex gap-3">\n                <button onclick="closeModal(\'modal-bonus-note\')" class="flex-1 py-2.5 rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-600 font-extrabold text-xs">\n                    取消\n                </button>\n                <button id="bonus-modal-confirm-btn" onclick="confirmBonusTask()" class="flex-1 py-2.5 rounded-2xl bg-gradient-to-r from-amber-400 to-orange-400 hover:from-amber-500 hover:to-orange-500 text-white font-black text-xs shadow-sm">\n                    🌟 完成打卡 (+150分)\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <!-- MODAL 3: SETTINGS & DUAL THEME SELECTOR -->\n    <div id="modal-settings" onclick="if(event.target === this) cancelSettingsModal()" class="fixed inset-0 z-50 bg-[#2E2545]/45 backdrop-blur-xs hidden items-center justify-center p-3 sm:p-5">\n        <div class="bg-white rounded-[32px] max-w-lg w-full border-2 border-violet-200 shadow-pastel animate-pop max-h-[88vh] flex flex-col overflow-hidden">\n            <!-- 1. 固定顶部 Header -->\n            <div class="px-6 py-4 border-b-2 border-dashed border-violet-100 flex items-center justify-between shrink-0 bg-white">\n                <div>\n                    <h3 class="font-black text-[#2E2545] text-lg">⚙️ 家长设置 & 主题风格切换</h3>\n                    <p class="text-xs font-bold text-[#7E7494]">支持一键切换女生/男生专属马卡龙配色与个人独立空间</p>\n                </div>\n                <button type="button" onclick="cancelSettingsModal()" class="w-8 h-8 rounded-full bg-violet-100 hover:bg-violet-200 text-violet-700 flex items-center justify-center font-black transition cursor-pointer">✕</button>\n            </div>\n\n            <!-- 2. 内部独立滚动区域 Body -->\n            <div class="p-6 overflow-y-auto space-y-4 flex-1 min-h-0">\n                <div>\n                    <label class="text-xs font-extrabold text-[#5E5475] block mb-2">🎨 选择主题配色风格（点击即可实时预览）</label>\n                    <div class="grid grid-cols-2 gap-3">\n                        <button type="button" onclick="previewThemeSelection(\'girl\')" id="theme-card-girl" class="p-3.5 rounded-2xl border-2 text-left transition-all flex items-center gap-3 cursor-pointer bg-[#FAF8FF] border-[#8B7CF6] ring-2 ring-violet-200">\n                            <div class="w-11 h-11 rounded-2xl bg-gradient-to-br from-[#A78BFA] to-[#8B7CF6] flex items-center justify-center text-2xl text-white shrink-0 shadow-xs">\n                                🦄\n                            </div>\n                            <div class="min-w-0">\n                                <div class="text-xs sm:text-sm font-black text-[#2E2545] truncate">星光少女版</div>\n                                <div class="text-[11px] font-bold text-violet-600">🌸 梦幻紫罗兰</div>\n                            </div>\n                        </button>\n\n                        <button type="button" onclick="previewThemeSelection(\'boy\')" id="theme-card-boy" class="p-3.5 rounded-2xl border-2 text-left transition-all flex items-center gap-3 cursor-pointer bg-[#F4F9FF] border-sky-200 hover:border-sky-400">\n                            <div class="w-11 h-11 rounded-2xl bg-gradient-to-br from-[#38BDF8] to-[#2563EB] flex items-center justify-center text-2xl text-white shrink-0 shadow-xs">\n                                🚀\n                            </div>\n                            <div class="min-w-0">\n                                <div class="text-xs sm:text-sm font-black text-slate-800 truncate">星际少年版</div>\n                                <div class="text-[11px] font-bold text-blue-600">⚡ 星际晴空蓝</div>\n                            </div>\n                        </button>\n                    </div>\n                </div>\n\n                <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">🌟 小朋友专属昵称 (选填)</label>\n                        <input type="text" id="set-child-nickname" placeholder="例如：朵朵 / 乐乐" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-bold bg-violet-50/40 focus:bg-white focus:outline-none focus:border-violet-500">\n                    </div>\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">🏷️ 打卡站主标题 (可自定义)</label>\n                        <input type="text" id="set-child-name" placeholder="星光少女成长打卡站" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-bold bg-violet-50/40 focus:bg-white focus:outline-none focus:border-violet-500">\n                    </div>\n                </div>\n\n                <div class="grid grid-cols-2 gap-3">\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">🔑 当前家长 PIN 码 <span class="text-rose-500">*</span></label>\n                        <input type="password" id="set-old-pin" maxlength="4" inputmode="numeric" placeholder="默认 1234" class="w-full px-3 py-2.5 rounded-2xl border-2 border-violet-200 text-sm text-center tracking-widest font-black bg-violet-50/40">\n                    </div>\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">新 PIN 码 (留空不改)</label>\n                        <input type="password" id="set-new-pin" maxlength="4" inputmode="numeric" placeholder="4位数字" class="w-full px-3 py-2.5 rounded-2xl border-2 border-violet-200 text-sm text-center tracking-widest font-black bg-violet-50/40">\n                    </div>\n                </div>\n\n                <div class="flex items-center justify-between p-3.5 rounded-2xl bg-slate-50 border border-slate-200/80">\n                    <div class="flex items-center gap-2.5">\n                        <span class="text-xl">🔔</span>\n                        <div>\n                            <div class="text-xs font-black text-[#2E2545]">打卡与奖励音效</div>\n                            <div class="text-[11px] font-bold text-[#7E7494]">任务勾选、兑换心愿与升级滑音提示</div>\n                        </div>\n                    </div>\n                    <button type="button" onclick="toggleSound()" id="sound-btn" class="px-3.5 py-1.5 rounded-xl font-extrabold text-xs transition border flex items-center gap-1.5 shadow-2xs bg-emerald-100 text-emerald-800 border-emerald-200 cursor-pointer">\n                        <span id="sound-icon">🔊</span>\n                        <span id="sound-status-text">已开启</span>\n                    </button>\n                </div>\n\n                <div class="flex items-center justify-between p-3.5 rounded-2xl bg-amber-50/70 border border-amber-200/80">\n                    <div class="flex items-center gap-2.5">\n                        <span class="text-xl">🎯</span>\n                        <div>\n                            <div class="text-xs font-black text-[#2E2545]">自定义各任务打卡分值</div>\n                            <div class="text-[11px] font-bold text-[#7E7494]">按孩子成长阶段，自主调节每项打卡激励分值</div>\n                        </div>\n                    </div>\n                    <button type="button" onclick="openTaskPointsModal()" class="px-3.5 py-1.5 rounded-xl font-extrabold text-xs transition border flex items-center gap-1 shadow-2xs bg-white text-amber-900 border-amber-200 hover:bg-amber-50 cursor-pointer active:scale-95">\n                        <span>✏️ 调整分值</span>\n                    </button>\n                </div>\n\n                <div class="pt-3 border-t-2 border-dashed border-violet-100">\n                    <div class="flex items-center justify-between px-1 pt-1">\n                        <div>\n                            <div class="text-xs font-black text-[#2E2545]">🔄 清空今日卡片勾选状态</div>\n                            <div class="text-[11px] font-bold text-[#7E7494]">把今天所有勾选项恢复为未选</div>\n                        </div>\n                        <button type="button" onclick="resetTodayBoardWithPin()" class="px-3.5 py-2 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 font-extrabold text-xs border border-rose-200 transition cursor-pointer">\n                            重置今日勾选\n                        </button>\n                    </div>\n                </div>\n\n                <p id="settings-msg" class="text-xs font-extrabold text-rose-600 mt-2 hidden text-center"></p>\n            </div>\n\n            <!-- 3. 固定底部 Footer -->\n            <div class="px-6 py-4 border-t-2 border-dashed border-violet-100 bg-white flex gap-3 shrink-0">\n                <button type="button" onclick="cancelSettingsModal()" class="flex-1 py-2.5 rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-600 font-extrabold text-xs transition cursor-pointer">取消</button>\n                <button type="button" onclick="saveSettings()" class="flex-1 py-2.5 rounded-2xl theme-primary-bg text-white font-extrabold text-xs shadow-sm hover:opacity-95 transition cursor-pointer">💾 保存设置（需输入当前PIN码）</button>\n            </div>\n        </div>\n    </div>\n\n    <!-- MODAL 7: CUSTOM TASK POINTS CONFIG -->\n    <div id="modal-custom-task-points" onclick="if(event.target === this) closeModal(\'modal-custom-task-points\')" class="fixed inset-0 z-50 bg-[#2E2545]/45 backdrop-blur-xs hidden items-center justify-center p-3 sm:p-5">\n        <div class="bg-white rounded-[32px] max-w-lg w-full border-2 border-amber-200 shadow-pastel animate-pop max-h-[86vh] flex flex-col overflow-hidden">\n            <!-- 1. 固定顶部 Header -->\n            <div class="px-6 py-4 border-b-2 border-dashed border-amber-100 flex items-center justify-between shrink-0 bg-white">\n                <div class="flex items-center gap-2.5 min-w-0">\n                    <div class="w-10 h-10 rounded-2xl bg-amber-100 text-amber-600 flex items-center justify-center text-xl border border-amber-200 shrink-0">🎯</div>\n                    <div class="min-w-0">\n                        <h3 class="font-black text-[#2E2545] text-base sm:text-lg truncate">各任务打卡分值自定义</h3>\n                        <p class="text-[11px] sm:text-xs font-bold text-[#7E7494] truncate">按孩子成长阶段调节激励权重（需家长 PIN 码）</p>\n                    </div>\n                </div>\n                <button onclick="closeModal(\'modal-custom-task-points\')" class="w-8 h-8 rounded-full bg-amber-50 text-amber-600 font-bold hover:bg-amber-100 cursor-pointer shrink-0 transition">✕</button>\n            </div>\n\n            <!-- 2. 中间独立滚动区（滚动条内嵌，绝对限制在视口与圆角卡片内部） -->\n            <div class="flex-1 overflow-y-auto px-6 py-4 custom-modal-scroll">\n                <div id="task-points-list" class="space-y-4 divide-y divide-dashed divide-slate-100 pr-1">\n                    <!-- 动态生成各任务分值输入框 -->\n                </div>\n            </div>\n\n            <!-- 3. 固定底部 Footer（PIN 码与保存操作区） -->\n            <div class="px-6 py-3.5 bg-amber-50/50 border-t-2 border-dashed border-amber-100 shrink-0 space-y-2.5">\n                <div class="flex items-center justify-between gap-2 bg-white px-3.5 py-2 rounded-2xl border border-amber-200">\n                    <label class="text-xs font-extrabold text-amber-900 shrink-0">\n                        🔑 家长 4 位 PIN 码（默认 1234）：\n                    </label>\n                    <input type="password" id="task-points-pin" maxlength="4" inputmode="numeric" placeholder="••••" class="w-24 px-2.5 py-1 rounded-xl border border-amber-300 text-xs font-black text-center tracking-widest bg-amber-50/30 focus:outline-none focus:border-amber-500">\n                </div>\n                <p id="task-points-error" class="text-xs font-extrabold text-rose-600 hidden text-center"></p>\n\n                <div class="flex gap-2.5">\n                    <button onclick="resetDefaultTaskPoints()" type="button" class="px-3.5 py-2.5 rounded-2xl bg-white hover:bg-slate-100 border border-slate-200 text-slate-700 font-extrabold text-xs shrink-0 cursor-pointer transition">\n                        🔄 恢复默认\n                    </button>\n                    <button onclick="closeModal(\'modal-custom-task-points\')" type="button" class="flex-1 py-2.5 rounded-2xl bg-white hover:bg-slate-100 border border-slate-200 text-slate-600 font-extrabold text-xs cursor-pointer transition">\n                        取消\n                    </button>\n                    <button onclick="saveCustomTaskPoints()" type="button" class="flex-1 py-2.5 rounded-2xl bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-white font-extrabold text-xs shadow-sm cursor-pointer transition">\n                        💾 保存分值\n                    </button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n        <!-- MODAL 6: PERSONAL INDEPENDENT SPACE -->\n    <div id="modal-share" onclick="if(event.target === this) closeModal(\'modal-share\')" class="fixed inset-0 z-50 bg-[#2E2545]/45 backdrop-blur-xs hidden items-center justify-center p-3 sm:p-5">\n        <div class="bg-white rounded-[28px] sm:rounded-[32px] max-w-md w-full p-4 sm:p-6 border-2 border-emerald-200 shadow-pastel animate-pop max-h-[88vh] overflow-y-auto">\n            <!-- 头部：标题与关闭按钮（响应式对齐，防止小屏幕折行变形） -->\n            <div class="flex items-start justify-between pb-3.5 border-b-2 border-dashed border-emerald-100 gap-2">\n                <div class="flex items-center gap-2.5 min-w-0">\n                    <div id="space-modal-icon" class="w-10 h-10 rounded-2xl bg-emerald-100 text-emerald-700 flex items-center justify-center text-xl border border-emerald-200 shrink-0">👧</div>\n                    <div class="min-w-0">\n                        <h3 class="font-black text-[#2E2545] text-base sm:text-lg leading-tight truncate">个人独立空间</h3>\n                        <p class="text-[11px] sm:text-xs font-bold text-[#7E7494] mt-0.5 truncate">多宝贝专属独立打卡空间与账本</p>\n                    </div>\n                </div>\n                <button onclick="closeModal(\'modal-share\')" class="w-8 h-8 rounded-full bg-emerald-50 text-emerald-600 font-bold hover:bg-emerald-100 flex items-center justify-center shrink-0 cursor-pointer transition">✕</button>\n            </div>\n\n            <!-- 主内容区 -->\n            <div class="mt-4 space-y-3.5">\n                <!-- 当前所在空间卡片 -->\n                <div class="p-3 rounded-2xl bg-emerald-50/60 border border-emerald-200/90 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2">\n                    <div class="flex items-center gap-1.5 min-w-0">\n                        <span class="text-xs font-bold text-emerald-800 shrink-0">当前空间：</span>\n                        <span id="modal-current-space-name" class="text-xs font-black text-emerald-950 truncate bg-white px-2 py-0.5 rounded-lg border border-emerald-200">个人空间</span>\n                    </div>\n                    <span id="cloud-sync-indicator" class="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-white text-emerald-700 border border-emerald-200 shrink-0 self-start sm:self-auto">\n                        独立存储已就绪\n                    </span>\n                </div>\n\n                <!-- 切换空间表单卡片 -->\n                <div class="bg-white rounded-2xl p-3.5 border-2 border-emerald-200/80 shadow-2xs space-y-2.5">\n                    <label class="block text-xs font-black text-[#2E2545]">\n                        🔑 输入空间暗号（支持小朋友姓名拼音/英文）：\n                    </label>\n                    <!-- 移动端纵向堆叠，桌面端横向排列，大拇指极易点击 -->\n                    <div class="flex flex-col sm:flex-row gap-2">\n                        <input type="text" id="space-id-input" placeholder="例如：duoduo / leo" onkeydown="if(event.key===\'Enter\') switchFamilySpace()" class="w-full sm:flex-1 px-3.5 py-2 rounded-xl border-2 border-emerald-200 text-xs sm:text-sm font-black text-emerald-950 bg-emerald-50/20 focus:outline-none focus:border-emerald-500 focus:bg-white transition">\n                        <button onclick="switchFamilySpace()" class="w-full sm:w-auto px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-black text-xs shrink-0 cursor-pointer active:scale-95 transition shadow-2xs">\n                            切换/进入\n                        </button>\n                    </div>\n\n                    <!-- 快捷建议标签 -->\n                    <div class="flex items-center gap-1.5 flex-wrap pt-1">\n                        <span class="text-[10px] font-bold text-[#7E7494]">快捷：</span>\n                        <button type="button" onclick="document.getElementById(\'space-id-input\').value=\'\'; switchFamilySpace();" class="text-[10px] font-extrabold px-2 py-0.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-600 cursor-pointer transition">\n                            🏠 默认空间\n                        </button>\n                    </div>\n                </div>\n\n                <!-- 规则提示说明 -->\n                <div class="p-3 rounded-2xl bg-slate-50 border border-slate-100 text-[11px] font-bold text-[#7E7494] space-y-1 leading-relaxed">\n                    <p class="flex items-start gap-1">\n                        <span class="shrink-0">💡</span>\n                        <span>每位小朋友输入不同暗号（1-24位字母、数字），打卡记录、积分与等级将完全独立隔离保存。</span>\n                    </p>\n                    <p class="flex items-start gap-1">\n                        <span class="shrink-0">🔑</span>\n                        <span>新创建空间的初始家长 PIN 码默认为 <code class="bg-white px-1 rounded border border-slate-200 text-slate-800 font-black">1234</code>。</span>\n                    </p>\n                </div>\n            </div>\n\n            <!-- 底部操作按钮 -->\n            <div class="mt-4">\n                <button onclick="closeModal(\'modal-share\')" class="w-full py-2.5 rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-extrabold text-xs transition cursor-pointer">\n                    完成并关闭\n                </button>\n            </div>\n        </div>\n    </div>\n\n        <!-- MODAL 2: PARENT FINAL SETTLEMENT -->\n    <div id="modal-settlement" onclick="if(event.target === this) closeModal(\'modal-settlement\')" class="fixed inset-0 z-50 bg-[#2E2545]/45 backdrop-blur-xs hidden items-center justify-center p-3 sm:p-5">\n        <div class="bg-white rounded-[32px] max-w-lg w-full border-2 border-violet-200 shadow-pastel animate-pop max-h-[88vh] flex flex-col overflow-hidden">\n            <!-- 1. 固定顶部 Header -->\n            <div class="px-6 py-4 border-b-2 border-dashed border-violet-100 flex items-center justify-between shrink-0 bg-white">\n                <div class="flex items-center gap-3">\n                    <div class="w-11 h-11 rounded-2xl bg-violet-100 text-violet-600 flex items-center justify-center text-2xl border border-violet-200 shrink-0">\n                        👑\n                    </div>\n                    <div>\n                        <div class="flex items-center gap-2">\n                            <h3 class="font-black text-[#2E2545] text-lg">家长最终核算确认</h3>\n                            <span id="modal-settle-badge" class="text-[11px] font-extrabold px-2.5 py-0.5 rounded-full bg-violet-100 text-violet-700">首次提交</span>\n                        </div>\n                        <p class="text-xs font-bold text-[#7E7494]">当日多次提交仅以最后一次为准，自动覆盖差额</p>\n                    </div>\n                </div>\n                <button type="button" onclick="closeModal(\'modal-settlement\')" class="w-8 h-8 rounded-full bg-violet-100 hover:bg-violet-200 text-violet-700 flex items-center justify-center font-black transition cursor-pointer">✕</button>\n            </div>\n\n            <!-- 2. 内部独立滚动区域 Body -->\n            <div class="p-6 overflow-y-auto space-y-4 flex-1 min-h-0">\n                <div id="modal-overwrite-alert" class="hidden bg-gradient-to-r from-violet-50 to-emerald-50 border-2 border-violet-200 rounded-2xl p-3.5">\n                    <div class="text-xs font-black text-violet-900 flex items-center gap-1.5">\n                        <span>🔄</span>\n                        <span>同日覆盖结算模式（以最后一次提交为准）</span>\n                    </div>\n                    <p id="modal-overwrite-detail" class="text-xs font-bold text-[#5E5475] mt-1 leading-relaxed"></p>\n                </div>\n\n                <div>\n                    <div class="flex items-center justify-between text-xs font-extrabold text-[#6E6385] mb-2">\n                        <span>📋 今日勾选完成项目清单</span>\n                        <span id="modal-pending-count" class="text-violet-700">0 项</span>\n                    </div>\n                    <div id="modal-task-list" class="bg-[#FAF8FF] rounded-2xl p-3 space-y-2 max-h-44 overflow-y-auto border-2 border-violet-100"></div>\n                </div>\n\n                <div class="space-y-2.5">\n                    <div class="text-xs font-extrabold text-[#6E6385]">⚡ 家长额外激励加成（可勾选）：</div>\n\n                    <label class="flex items-center justify-between p-3.5 rounded-2xl bg-emerald-50/70 border-2 border-emerald-200/80 hover:border-emerald-300 cursor-pointer transition">\n                        <div class="flex items-center gap-3">\n                            <input type="checkbox" id="parent-speed-bonus" onchange="updateSettlementTotalPreview()" class="w-5 h-5 accent-emerald-500 rounded-lg cursor-pointer">\n                            <div>\n                                <div class="text-xs sm:text-sm font-black text-emerald-950">🚀 今日高效不拖拉奖（早鸟加成）</div>\n                                <div class="text-[11px] font-bold text-emerald-700">在约定时间前主动清空必做任务，专注不磨蹭</div>\n                            </div>\n                        </div>\n                        <span id="settle-speed-pts-badge" class="text-xs font-black text-emerald-700 bg-white px-2.5 py-1 rounded-full border border-emerald-200 shrink-0">+1.5 分</span>\n                    </label>\n\n                    <label class="flex items-center justify-between p-3.5 rounded-2xl bg-pink-50/70 border-2 border-pink-200/80 hover:border-pink-300 cursor-pointer transition">\n                        <div class="flex items-center gap-3">\n                            <input type="checkbox" id="parent-neat-bonus" onchange="updateSettlementTotalPreview()" class="w-5 h-5 accent-pink-500 rounded-lg cursor-pointer">\n                            <div>\n                                <div class="text-xs sm:text-sm font-black text-pink-950">✍️ 卷面书写工整暴击奖</div>\n                                <div class="text-[11px] font-bold text-pink-700">字迹端正清爽，错题订正认真到位</div>\n                            </div>\n                        </div>\n                        <span id="settle-neat-pts-badge" class="text-xs font-black text-pink-700 bg-white px-2.5 py-1 rounded-full border border-pink-200 shrink-0">+1.5 分</span>\n                    </label>\n                </div>\n\n                <div class="bg-violet-50/90 rounded-2xl p-4 border-2 border-violet-200 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">\n                    <div>\n                        <span class="text-xs font-extrabold text-violet-700 block">本次最终核算总分</span>\n                        <div class="flex items-baseline gap-2 mt-0.5">\n                            <span id="modal-total-score" class="text-3xl font-black text-violet-900">0 分</span>\n                            <span id="modal-net-diff" class="hidden text-xs font-extrabold px-2 py-0.5 rounded-full"></span>\n                        </div>\n                    </div>\n                    <div class="w-full sm:w-auto">\n                        <label class="text-xs font-extrabold text-violet-800 block mb-1">🔑 家长 4 位 PIN 码</label>\n                        <input type="password" id="settlement-pin" maxlength="4" inputmode="numeric" placeholder="默认 1234" class="w-full sm:w-36 text-center tracking-widest font-black text-base px-3 py-2 rounded-xl border-2 border-violet-300 focus:outline-none focus:border-violet-600 bg-white text-violet-900">\n                    </div>\n                </div>\n\n                <p id="settlement-error" class="text-xs font-extrabold text-rose-600 mt-1 hidden text-center"></p>\n            </div>\n\n            <!-- 3. 固定底部 Footer -->\n            <div class="px-6 py-4 border-t-2 border-dashed border-violet-100 bg-white flex gap-3 shrink-0">\n                <button type="button" onclick="closeModal(\'modal-settlement\')" class="flex-1 py-3 rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-600 font-extrabold text-xs sm:text-sm transition cursor-pointer">\n                    返回修改\n                </button>\n                <button type="button" onclick="confirmSettlement()" class="flex-1 py-3 rounded-2xl theme-jelly-btn text-white font-black text-xs sm:text-sm transition cursor-pointer">\n                    ✨ 确认核算（以此为准）\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <!-- MODAL 4: ADD REWARD -->\n    <div id="modal-add-reward" class="fixed inset-0 z-50 bg-[#2E2545]/40 backdrop-blur-xs hidden items-center justify-center p-4">\n        <div class="bg-white rounded-[32px] max-w-md w-full p-6 border-2 border-pink-200 shadow-pastel animate-pop">\n            <div class="flex items-center justify-between pb-3.5 border-b-2 border-dashed border-pink-100">\n                <h3 class="font-black text-[#2E2545] text-lg">🎁 新增心愿奖品</h3>\n                <button onclick="closeModal(\'modal-add-reward\')" class="w-8 h-8 rounded-full bg-pink-50 text-pink-600 font-bold">✕</button>\n            </div>\n            <div class="mt-4 space-y-3">\n                <div>\n                    <label class="text-xs font-extrabold text-[#5E5475] block mb-1">心愿图标 (Emoji)</label>\n                    <input type="text" id="reward-icon-input" value="🎮" maxlength="2" class="w-20 text-center text-xl px-3 py-2 rounded-2xl border-2 border-violet-200 bg-violet-50/40">\n                </div>\n                <div>\n                    <div class="flex items-center justify-between mb-1">\n                        <label class="text-xs font-extrabold text-[#5E5475] block">心愿名称（少于15个字）</label>\n                        <span id="reward-title-count" class="text-[11px] font-bold text-violet-500">0/14字</span>\n                    </div>\n                    <input type="text" id="reward-title-input" maxlength="14" oninput="updateAddTitleCount()" placeholder="例如：买喜欢的文具 / 玩25分钟游戏" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-bold bg-violet-50/40">\n                </div>\n                <div class="grid grid-cols-2 gap-3">\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">所需积分</label>\n                        <input type="number" id="reward-cost-input" value="50" min="5" step="5" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-black bg-violet-50/40">\n                    </div>\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">家长 PIN 码</label>\n                        <input type="password" id="reward-pin-input" maxlength="4" inputmode="numeric" placeholder="默认 1234" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm text-center tracking-widest font-black bg-violet-50/40">\n                    </div>\n                </div>\n            </div>\n            <p id="reward-error" class="text-xs font-extrabold text-rose-600 mt-2.5 hidden text-center"></p>\n            <div class="mt-5 flex gap-3">\n                <button onclick="closeModal(\'modal-add-reward\')" class="flex-1 py-2.5 rounded-2xl bg-slate-100 text-slate-600 font-extrabold text-xs">取消</button>\n                <button onclick="saveNewReward()" class="flex-1 py-2.5 rounded-2xl bg-[#8B7CF6] hover:bg-violet-600 text-white font-extrabold text-xs">确认上架</button>\n            </div>\n        </div>\n    </div>\n\n    <!-- MODAL 4B: MANAGE REWARDS -->\n    <div id="modal-manage-rewards" class="fixed inset-0 z-50 bg-[#2E2545]/40 backdrop-blur-xs hidden items-center justify-center p-4">\n        <div class="bg-white rounded-[32px] max-w-md w-full p-6 border-2 border-violet-200 shadow-pastel animate-pop">\n            <div class="flex items-center justify-between pb-3.5 border-b-2 border-dashed border-violet-100">\n                <div class="flex items-center gap-2">\n                    <span class="text-xl">✏️</span>\n                    <h3 class="font-black text-[#2E2545] text-lg">家长调整既往心愿</h3>\n                </div>\n                <button onclick="closeModal(\'modal-manage-rewards\')" class="w-8 h-8 rounded-full bg-violet-50 text-violet-600 font-bold">✕</button>\n            </div>\n            <p class="text-xs font-bold text-[#7E7494] mt-2.5 mb-3">\n                选择需要调整的心愿，可修改心愿描述（少于15个字）及积分：\n            </p>\n            <div id="manage-rewards-list" class="max-h-72 overflow-y-auto space-y-2.5 pr-1"></div>\n            <div class="mt-4 pt-3 border-t border-violet-100 flex justify-end">\n                <button onclick="closeModal(\'modal-manage-rewards\')" class="px-5 py-2 rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-600 font-extrabold text-xs transition">\n                    关闭\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <!-- MODAL 4C: EDIT REWARD -->\n    <div id="modal-edit-reward" class="fixed inset-0 z-50 bg-[#2E2545]/40 backdrop-blur-xs hidden items-center justify-center p-4">\n        <div class="bg-white rounded-[32px] max-w-md w-full p-6 border-2 border-violet-200 shadow-pastel animate-pop">\n            <div class="flex items-center justify-between pb-3.5 border-b-2 border-dashed border-violet-100">\n                <h3 class="font-black text-[#2E2545] text-lg">✏️ 调整心愿描述与积分</h3>\n                <button onclick="closeModal(\'modal-edit-reward\')" class="w-8 h-8 rounded-full bg-violet-50 text-violet-600 font-bold">✕</button>\n            </div>\n            <input type="hidden" id="edit-reward-id">\n            <div class="mt-4 space-y-3">\n                <div>\n                    <label class="text-xs font-extrabold text-[#5E5475] block mb-1">心愿图标 (Emoji)</label>\n                    <input type="text" id="edit-reward-icon-input" maxlength="2" class="w-20 text-center text-xl px-3 py-2 rounded-2xl border-2 border-violet-200 bg-violet-50/40">\n                </div>\n                <div>\n                    <div class="flex items-center justify-between mb-1">\n                        <label class="text-xs font-extrabold text-[#5E5475] block">心愿描述（必须少于15个字）</label>\n                        <span id="edit-reward-title-count" class="text-[11px] font-bold text-violet-500">0/14字</span>\n                    </div>\n                    <input type="text" id="edit-reward-title-input" maxlength="14" oninput="updateEditTitleCount()" placeholder="例如：玩 25 分钟游戏" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-bold bg-violet-50/40">\n                </div>\n                <div class="grid grid-cols-2 gap-3">\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">所需积分</label>\n                        <input type="number" id="edit-reward-cost-input" min="1" step="1" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-black bg-violet-50/40">\n                    </div>\n                    <div>\n                        <label class="text-xs font-extrabold text-[#5E5475] block mb-1">家长 PIN 码</label>\n                        <input type="password" id="edit-reward-pin-input" maxlength="4" inputmode="numeric" placeholder="默认 1234" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm text-center tracking-widest font-black bg-violet-50/40">\n                    </div>\n                </div>\n            </div>\n            <p id="edit-reward-error" class="text-xs font-extrabold text-rose-600 mt-2.5 hidden text-center"></p>\n            <div class="mt-5 flex gap-3">\n                <button onclick="closeModal(\'modal-edit-reward\')" class="flex-1 py-2.5 rounded-2xl bg-slate-100 text-slate-600 font-extrabold text-xs">取消</button>\n                <button onclick="submitEditReward()" class="flex-1 py-2.5 rounded-2xl bg-[#8B7CF6] hover:bg-violet-600 text-white font-extrabold text-xs">确认调整</button>\n            </div>\n        </div>\n    </div>\n\n    <!-- MODAL 5: MANUAL POINTS ADJUST -->\n    <div id="modal-manual-adjust" class="fixed inset-0 z-50 bg-[#2E2545]/40 backdrop-blur-xs hidden items-center justify-center p-4">\n        <div class="bg-white rounded-[32px] max-w-md w-full p-6 border-2 border-amber-200 shadow-pastel animate-pop">\n            <div class="flex items-center justify-between pb-3.5 border-b-2 border-dashed border-amber-100">\n                <h3 class="font-black text-[#2E2545] text-lg">⚡ 家长手动奖惩调分</h3>\n                <button onclick="closeModal(\'modal-manual-adjust\')" class="w-8 h-8 rounded-full bg-amber-50 text-amber-600 font-bold">✕</button>\n            </div>\n            <div class="mt-4 space-y-3">\n                <div>\n                    <label class="text-xs font-extrabold text-[#5E5475] block mb-1">调整分值（正数加分，负数扣分，支持 0.5 小数）</label>\n                    <input type="number" id="adjust-points-input" value="2" step="0.5" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-black bg-violet-50/40">\n                </div>\n                <div>\n                    <label class="text-xs font-extrabold text-[#5E5475] block mb-1">奖惩原因备注</label>\n                    <input type="text" id="adjust-reason-input" placeholder="例如：主动帮家里分担家务 / 单元测验进步" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm font-bold bg-violet-50/40">\n                </div>\n                <div>\n                    <label class="text-xs font-extrabold text-[#5E5475] block mb-1">家长 PIN 码</label>\n                    <input type="password" id="adjust-pin-input" maxlength="4" inputmode="numeric" placeholder="默认 1234" class="w-full px-3.5 py-2.5 rounded-2xl border-2 border-violet-200 text-sm text-center tracking-widest font-black bg-violet-50/40">\n                </div>\n            </div>\n            <p id="adjust-error" class="text-xs font-extrabold text-rose-600 mt-2.5 hidden text-center"></p>\n            <div class="mt-5 flex gap-3">\n                <button onclick="closeModal(\'modal-manual-adjust\')" class="flex-1 py-2.5 rounded-2xl bg-slate-100 text-slate-600 font-extrabold text-xs">取消</button>\n                <button onclick="confirmManualAdjust()" class="flex-1 py-2.5 rounded-2xl bg-[#8B7CF6] hover:bg-violet-600 text-white font-extrabold text-xs">确认执行</button>\n            </div>\n        </div>\n    </div>\n\n    <script>\n        const SPEED_BONUS_PTS = 1.5;\n        const NEAT_BONUS_PTS = 1.5;\n\n        function roundScore(num) {\n            return Math.round((Number(num) + Number.EPSILON) * 100) / 100;\n        }\n\n        const TASKS = [\n            { id: \'school_math\', group: \'school\', title: \'校内数学作业\', desc: \'完成当日数学作业 + 错题闭环订正\', points: 1, icon: \'📐\', color: \'sky\' },\n            { id: \'school_chinese\', group: \'school\', title: \'校内语文作业\', desc: \'生字词默写 / 课文背诵 / 课内作业\', points: 1, icon: \'📖\', color: \'sakura\' },\n            { id: \'school_english\', group: \'school\', title: \'校内英语作业\', desc: \'课内原音跟读与同步书写练习\', points: 1, icon: \'🔤\', color: \'lavender\' },\n            { id: \'self_english\', group: \'selfstudy\', title: \'自学拓展 · 英语\', desc: \'原版分级阅读 / 单词闯关 / 听力输入\', points: 2, icon: \'🎧\', color: \'lavender\' },\n            { id: \'self_math\', group: \'selfstudy\', title: \'自学拓展 · 数学\', desc: \'思维拓展题 / 算力微练 / 新课预习\', points: 2, icon: \'🧮\', color: \'sky\' },\n            { id: \'self_chinese\', group: \'selfstudy\', title: \'自学拓展 · 语文\', desc: \'古诗文诵读 / 每日好词好句摘抄积累\', points: 2, icon: \'✒️\', color: \'sakura\' },\n            { id: \'habit_pack\', group: \'habit\', title: \'个人日常好习惯\', desc: \'书包整理与桌面清空 · 规律起居自律\', points: 0.5, icon: \'🎒\', color: \'mint\' },\n            { id: \'bonus_book\', group: \'bonus\', title: \'书籍 · 完整阅读一本书\', desc: \'读完一本大部头课外书并分享核心情节\', points: 150, icon: \'📚\', color: \'butter\', prompt: \'📚 写下今天读完的书名吧（选填）：\' },\n            { id: \'bonus_english\', group: \'bonus\', title: \'英语 · 进阶深度挑战\', desc: \'完成一套高阶同步自测或原版流利复述\', points: 15, icon: \'🏆\', color: \'butter\', prompt: \'🏆 写下今天完成的英语进阶内容（选填）：\' },\n            { id: \'bonus_math\', group: \'bonus\', title: \'数学 · 压轴思维攻坚\', desc: \'独立攻克高难度思维题并给家长讲清思路\', points: 15, icon: \'🧠\', color: \'butter\', prompt: \'🧠 写下今天攻克的数学难题类型（选填）：\' },\n            { id: \'bonus_chinese\', group: \'bonus\', title: \'语文 · 深度写作/读书笔记\', desc: \'自主完成一篇高质量习作或深度读书笔记\', points: 15, icon: \'📝\', color: \'butter\', prompt: \'📝 写下今天创作的文章题目（选填）：\' }\n        ];\n\n        const SPECIAL_BONUSES = [\n            { id: \'special_speed\', group: \'settle_bonus\', title: \'今日高效不拖拉奖（早鸟加成）\', desc: \'在约定时间前主动清空必做任务，专注不磨蹭\', points: 1.5, icon: \'🚀\', color: \'mint\' },\n            { id: \'special_neat\', group: \'settle_bonus\', title: \'卷面书写工整暴击奖\', desc: \'字迹端正清爽，主课错题订正认真到位\', points: 1.5, icon: \'✍️\', color: \'sakura\' }\n        ];\n\n        function getSpecialBonusPoints(key, defaultPts = 1.5) {\n            if (state && state.customTaskPoints && state.customTaskPoints[key] !== undefined) {\n                const val = Number(state.customTaskPoints[key]);\n                return isNaN(val) ? defaultPts : val;\n            }\n            return defaultPts;\n        }\n\n        function getAllConfigurableItems() {\n            return [...TASKS, ...SPECIAL_BONUSES];\n        }\n\n        const DEFAULT_REWARDS = [\n            { id: \'rw_1\', title: \'自由游戏 / 娱乐时间 20 分钟\', cost: 30, icon: \'🎮\' },\n            { id: \'rw_2\', title: \'免做一次小家务 / 睡前故事加场\', cost: 50, icon: \'🎟️\' },\n            { id: \'rw_3\', title: \'挑选心仪的文具 / 手账贴纸一套\', cost: 80, icon: \'🦄\' },\n            { id: \'rw_4\', title: \'周末全家大餐点菜决定权\', cost: 120, icon: \'🍕\' },\n            { id: \'rw_5\', title: \'兑换一本想看的课外书或零花钱\', cost: 160, icon: \'🎁\' },\n            { id: \'rw_6\', title: \'周末半天完全自由安排特权\', cost: 250, icon: \'🎡\' }\n        ];\n\n        const THEME_PRESETS = {\n            girl: {\n                defaultTitle: \'星光少女成长打卡站\',\n                avatar: \'🦄\',\n                subtitle: \'· 今日事今日毕，每一份努力都闪闪发光 ✨\',\n                levels: [\'Lv.1 星光初心学者\', \'Lv.2 梦幻专注达人\', \'Lv.3 紫罗兰自律骑士\', \'Lv.4 闪耀时间魔法师\', \'Lv.5 传奇星光女王\'],\n                confettiColors: [\'#A78BFA\', \'#F472B6\', \'#34D399\', \'#FBBF24\', \'#60A5FA\']\n            },\n            boy: {\n                defaultTitle: \'星际少年成长打卡站\',\n                avatar: \'🚀\',\n                subtitle: \'· 今日事今日毕，每一次探索都充满能量 ⚡\',\n                levels: [\'Lv.1 星际见习领航员\', \'Lv.2 极光专注先锋\', \'Lv.3 银河自律骑士\', \'Lv.4 超新星时间指挥官\', \'Lv.5 传奇星际舰长\'],\n                confettiColors: [\'#3B82F6\', \'#06B6D4\', \'#10B981\', \'#F59E0B\', \'#6366F1\']\n            }\n        };\n\n        let currentSpaceId = \'default\';\n        let previewingTheme = null;\n        let currentBonusTaskId = null;\n        let state = {};\n        let syncTimer = null;\n\n        function getTodayKey() {\n            const d = new Date();\n            const y = d.getFullYear();\n            const m = String(d.getMonth() + 1).padStart(2, \'0\');\n            const day = String(d.getDate()).padStart(2, \'0\');\n            return `${y}-${m}-${day}`;\n        }\n\n        function detectInitialSpaceId() {\n            try {\n                const params = new URLSearchParams(window.location.search);\n                const fromUrl = params.get(\'space\');\n                if (fromUrl && /^[a-zA-Z0-9_-]{1,24}$/.test(fromUrl)) {\n                    localStorage.setItem(\'STARLIGHT_LAST_SPACE_ID\', fromUrl.toLowerCase());\n                    return fromUrl.toLowerCase();\n                }\n            } catch (e) {}\n            return localStorage.getItem(\'STARLIGHT_LAST_SPACE_ID\') || \'default\';\n        }\n\n        function getStorageKey() {\n            return `STARLIGHT_GROWTH_V3_${currentSpaceId}`;\n        }\n\n        function createFreshDefaultState() {\n            const checks = {};\n            TASKS.forEach(t => { checks[t.id] = { checked: false, note: \'\' }; });\n            return {\n                theme: \'girl\',\n                studentName: \'星光少女成长打卡站\',\n                nickname: \'\',\n                pin: \'1234\',\n                soundEnabled: true,\n                totalPoints: 0,\n                totalXP: 0,\n                currentDateKey: getTodayKey(),\n                todayChecks: checks,\n                todaySpeedBonus: false,\n                todayNeatBonus: false,\n                dailySettlements: {},\n                rewards: JSON.parse(JSON.stringify(DEFAULT_REWARDS)),\n                history: [],\n                customTaskPoints: {},\n                updatedAt: 0\n            };\n        }\n\n        function normalizeAndRolloverState(targetState) {\n            if (!targetState.todayChecks) targetState.todayChecks = {};\n            TASKS.forEach(t => {\n                if (!targetState.todayChecks[t.id]) {\n                    targetState.todayChecks[t.id] = { checked: false, note: \'\' };\n                }\n            });\n            if (!targetState.customTaskPoints) targetState.customTaskPoints = {};\n            if (!targetState.dailySettlements) targetState.dailySettlements = {};\n            if (!Array.isArray(targetState.rewards) || targetState.rewards.length === 0) {\n                targetState.rewards = JSON.parse(JSON.stringify(DEFAULT_REWARDS));\n            }\n            if (!Array.isArray(targetState.history)) targetState.history = [];\n\n            const today = getTodayKey();\n            if (targetState.currentDateKey !== today) {\n                targetState.currentDateKey = today;\n                const todayRecord = targetState.dailySettlements[today];\n                if (todayRecord && todayRecord.checksSnapshot) {\n                    targetState.todayChecks = JSON.parse(JSON.stringify(todayRecord.checksSnapshot));\n                    targetState.todaySpeedBonus = !!todayRecord.speedBonus;\n                    targetState.todayNeatBonus = !!todayRecord.neatBonus;\n                } else {\n                    TASKS.forEach(t => { targetState.todayChecks[t.id] = { checked: false, note: \'\' }; });\n                    targetState.todaySpeedBonus = false;\n                    targetState.todayNeatBonus = false;\n                }\n                return true;\n            }\n            return false;\n        }\n\n        function getTaskPoints(task) {\n            if (state.customTaskPoints && state.customTaskPoints[task.id] !== undefined) {\n                const custom = parseFloat(state.customTaskPoints[task.id]);\n                if (!isNaN(custom) && custom > 0) return roundScore(custom);\n            }\n            return task.points;\n        }\n\n        function getEffectiveTasks() {\n            return TASKS.map(t => ({\n                ...t,\n                points: getTaskPoints(t)\n            }));\n        }\n\n        function updateCloudIndicator(text, isSuccess = true) {\n            const el = document.getElementById(\'cloud-sync-indicator\');\n            if (el) {\n                el.textContent = text;\n                el.className = isSuccess\n                    ? \'text-[11px] font-extrabold px-2 py-0.5 rounded-full bg-white text-emerald-700 border border-emerald-200\'\n                    : \'text-[11px] font-extrabold px-2 py-0.5 rounded-full bg-amber-50 text-amber-700 border border-amber-200\';\n            }\n            const dot = document.getElementById(\'space-sync-dot\');\n            if (dot) {\n                dot.className = isSuccess\n                    ? \'w-2 h-2 rounded-full bg-emerald-500 ring-2 ring-white shrink-0\'\n                    : \'w-2 h-2 rounded-full bg-amber-400 ring-2 ring-white shrink-0\';\n                dot.title = text;\n            }\n        }\n\n        function loadState() {\n            currentSpaceId = detectInitialSpaceId();\n            const raw = localStorage.getItem(getStorageKey());\n            const fresh = createFreshDefaultState();\n            if (raw) {\n                try {\n                    const parsed = JSON.parse(raw);\n                    state = { ...fresh, ...parsed };\n                } catch (e) {\n                    state = fresh;\n                }\n            } else {\n                state = fresh;\n            }\n\n            if (normalizeAndRolloverState(state)) {\n                saveState(false);\n            }\n\n            pullStateFromCloud();\n        }\n\n        async function pullStateFromCloud() {\n            try {\n                updateCloudIndicator(\'☁️ 正在同步云端...\');\n                const res = await fetch(`/api/state?space=${encodeURIComponent(currentSpaceId)}`, {\n                    method: \'GET\',\n                    headers: { \'Accept\': \'application/json\' }\n                });\n                if (!res.ok) return;\n                const result = await res.json();\n                if (!result.kvBound) {\n                    updateCloudIndicator(\'💾 本地存储模式 (未绑KV)\', false);\n                    return;\n                }\n                if (result.ok && result.data) {\n                    const cloudData = result.data;\n                    const localTime = Number(state.updatedAt || 0);\n                    const cloudTime = Number(cloudData.updatedAt || 0);\n                    if (cloudTime >= localTime || (state.history.length === 0 && state.totalPoints === 0)) {\n                        const fresh = createFreshDefaultState();\n                        state = { ...fresh, ...cloudData };\n                        normalizeAndRolloverState(state);\n                        localStorage.setItem(getStorageKey(), JSON.stringify(state));\n                        renderAll();\n                    } else if (localTime > cloudTime) {\n                        pushStateToCloud();\n                    }\n                    updateCloudIndicator(\'☁️ 云端 KV 已同步\');\n                } else if (result.ok && !result.data) {\n                    if (state.updatedAt > 0 || state.history.length > 0) {\n                        pushStateToCloud();\n                    } else {\n                        updateCloudIndicator(\'☁️ 云端 KV 已就绪\');\n                    }\n                }\n            } catch (e) {\n                updateCloudIndicator(\'💾 离线本地模式\', false);\n            }\n        }\n\n        function pushStateToCloud() {\n            if (syncTimer) clearTimeout(syncTimer);\n            syncTimer = setTimeout(async () => {\n                try {\n                    updateCloudIndicator(\'☁️ 正在保存至云端...\');\n                    const res = await fetch(`/api/state?space=${encodeURIComponent(currentSpaceId)}`, {\n                        method: \'POST\',\n                        headers: { \'Content-Type\': \'application/json\' },\n                        body: JSON.stringify(state)\n                    });\n                    const result = await res.json();\n                    if (result.ok && result.kvBound) {\n                        updateCloudIndicator(\'☁️ 云端 KV 已同步\');\n                    } else if (!result.kvBound) {\n                        updateCloudIndicator(\'💾 本地存储模式 (未绑KV)\', false);\n                    }\n                } catch (e) {\n                    updateCloudIndicator(\'⚠️ 云端暂未连接 (已存本地)\', false);\n                }\n            }, 250);\n        }\n\n        function saveState(syncCloud = true) {\n            state.updatedAt = Date.now();\n            try {\n                localStorage.setItem(getStorageKey(), JSON.stringify(state));\n            } catch (e) {}\n            if (syncCloud) {\n                pushStateToCloud();\n            }\n        }\n\n        let audioCtx = null;\n        function playSound(type) {\n            if (!state.soundEnabled) return;\n            try {\n                if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n                if (audioCtx.state === \'suspended\') audioCtx.resume();\n                const now = audioCtx.currentTime;\n\n                if (type === \'check\') {\n                    const osc = audioCtx.createOscillator();\n                    const gain = audioCtx.createGain();\n                    osc.type = \'sine\';\n                    osc.frequency.setValueAtTime(523.25, now);\n                    osc.frequency.exponentialRampToValueAtTime(783.99, now + 0.12);\n                    gain.gain.setValueAtTime(0.12, now);\n                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.16);\n                    osc.connect(gain);\n                    gain.connect(audioCtx.destination);\n                    osc.start(now);\n                    osc.stop(now + 0.16);\n                } else if (type === \'uncheck\') {\n                    const osc = audioCtx.createOscillator();\n                    const gain = audioCtx.createGain();\n                    osc.type = \'sine\';\n                    osc.frequency.setValueAtTime(587.33, now);\n                    osc.frequency.exponentialRampToValueAtTime(392.00, now + 0.10);\n                    gain.gain.setValueAtTime(0.10, now);\n                    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);\n                    osc.connect(gain);\n                    gain.connect(audioCtx.destination);\n                    osc.start(now);\n                    osc.stop(now + 0.14);\n                } else if (type === \'fanfare\') {\n                    const notes = [523.25, 659.25, 783.99, 1046.5];\n                    notes.forEach((freq, idx) => {\n                        const osc = audioCtx.createOscillator();\n                        const gain = audioCtx.createGain();\n                        osc.type = \'triangle\';\n                        osc.frequency.setValueAtTime(freq, now + idx * 0.07);\n                        gain.gain.setValueAtTime(0.14, now + idx * 0.07);\n                        gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.07 + 0.25);\n                        osc.connect(gain);\n                        gain.connect(audioCtx.destination);\n                        osc.start(now + idx * 0.07);\n                        osc.stop(now + idx * 0.07 + 0.25);\n                    });\n                }\n            } catch (e) {}\n        }\n\n        function updateSoundButtonVisual() {\n            const icon = document.getElementById(\'sound-icon\');\n            const text = document.getElementById(\'sound-status-text\');\n            const btn = document.getElementById(\'sound-btn\');\n            const isEnabled = !!state.soundEnabled;\n            if (icon) icon.textContent = isEnabled ? \'🔊\' : \'🔇\';\n            if (text) text.textContent = isEnabled ? \'已开启\' : \'已静音\';\n            if (btn) {\n                btn.className = isEnabled\n                    ? \'px-3.5 py-1.5 rounded-xl font-extrabold text-xs transition border flex items-center gap-1.5 shadow-2xs bg-emerald-100 text-emerald-800 border-emerald-200 cursor-pointer active:scale-95\'\n                    : \'px-3.5 py-1.5 rounded-xl font-extrabold text-xs transition border flex items-center gap-1.5 shadow-2xs bg-slate-100 text-slate-600 border-slate-200 cursor-pointer active:scale-95\';\n            }\n        }\n\n        function toggleSound() {\n            state.soundEnabled = !state.soundEnabled;\n            saveState();\n            updateSoundButtonVisual();\n            showToast(state.soundEnabled ? \'🔊 打卡音效已开启\' : \'🔇 打卡音效已静音\');\n        }\n\n        function applyThemeVisuals(themeKey) {\n            const isBoy = themeKey === \'boy\';\n            document.body.classList.toggle(\'theme-boy\', isBoy);\n            const preset = THEME_PRESETS[isBoy ? \'boy\' : \'girl\'];\n\n            const avatarBox = document.getElementById(\'theme-avatar-box\');\n            if (avatarBox) avatarBox.textContent = preset.avatar;\n\n            const spaceEmoji = document.getElementById(\'space-emoji\');\n            if (spaceEmoji) spaceEmoji.textContent = isBoy ? \'👦\' : \'👧\';\n            const spaceModalIcon = document.getElementById(\'space-modal-icon\');\n            if (spaceModalIcon) spaceModalIcon.textContent = isBoy ? \'👦\' : \'👧\';\n\n            const subText = document.getElementById(\'theme-subtitle-text\');\n            if (subText) {\n                subText.textContent = preset.subtitle;\n                subText.className = `hidden md:inline text-[11px] font-bold ${isBoy ? \'text-blue-600\' : \'text-[#8B7CF6]\'}`;\n            }\n\n            const scoreCard1 = document.getElementById(\'score-card-1\');\n            const scoreLabel1 = document.getElementById(\'score-card-1-label\');\n            const statWallet = document.getElementById(\'stat-wallet\');\n            const scoreUnit1 = document.getElementById(\'score-card-1-unit\');\n            const scoreCard1Icon = document.getElementById(\'score-card-1-icon\');\n            const levelCapsuleBox = document.getElementById(\'level-capsule-box\');\n            const levelBadge = document.getElementById(\'level-badge\');\n            const levelXpText = document.getElementById(\'level-xp-text\');\n            const xpText = document.getElementById(\'xp-text\');\n            const levelProgressBar = document.getElementById(\'level-progress-bar\');\n            const levelProgressBg = document.getElementById(\'level-progress-bg\');\n\n            if (isBoy) {\n                if (scoreCard1) scoreCard1.className = \'bg-gradient-to-br from-[#F0F7FF] to-[#DBEAFE] rounded-[22px] px-4 py-3 border border-blue-200 border-b-4 border-b-blue-300 shadow-sm flex flex-col justify-between gap-2.5 transition-all hover:-translate-y-0.5\';\n                if (scoreLabel1) scoreLabel1.className = \'text-[11px] font-extrabold text-blue-700 uppercase tracking-wider block\';\n                if (statWallet) statWallet.className = \'text-2xl sm:text-3xl font-black text-blue-950 leading-none\';\n                if (scoreUnit1) scoreUnit1.className = \'text-xs font-bold text-blue-700\';\n                if (scoreCard1Icon) scoreCard1Icon.className = \'w-11 h-11 rounded-2xl bg-white/90 border border-blue-100 shadow-2xs flex items-center justify-center text-2xl shrink-0\';\n                if (levelCapsuleBox) levelCapsuleBox.className = \'pt-2 border-t border-dashed border-blue-200/80 flex flex-col gap-1.5\';\n                if (levelBadge) levelBadge.className = \'px-2 py-0.5 rounded-md bg-blue-100 text-blue-700\';\n                if (levelXpText) levelXpText.className = \'text-blue-600 font-extrabold\';\n                if (xpText) xpText.className = \'text-blue-500/80 font-bold hidden sm:inline\';\n                if (levelProgressBar) levelProgressBar.className = \'h-full bg-gradient-to-r from-blue-500 to-cyan-500 rounded-full transition-all duration-300\';\n                if (levelProgressBg) levelProgressBg.className = \'w-full h-1.5 bg-blue-200/70 rounded-full overflow-hidden transition-colors\';\n            } else {\n                if (scoreCard1) scoreCard1.className = \'bg-gradient-to-br from-[#FAF8FF] to-[#EDE9FE] rounded-[22px] px-4 py-3 border border-violet-200 border-b-4 border-b-violet-300 shadow-sm flex flex-col justify-between gap-2.5 transition-all hover:-translate-y-0.5\';\n                if (scoreLabel1) scoreLabel1.className = \'text-[11px] font-extrabold text-violet-600 uppercase tracking-wider block\';\n                if (statWallet) statWallet.className = \'text-2xl sm:text-3xl font-black text-violet-900 leading-none\';\n                if (scoreUnit1) scoreUnit1.className = \'text-xs font-bold text-violet-600\';\n                if (scoreCard1Icon) scoreCard1Icon.className = \'w-11 h-11 rounded-2xl bg-white/90 border border-violet-100 shadow-2xs flex items-center justify-center text-2xl shrink-0\';\n                if (levelCapsuleBox) levelCapsuleBox.className = \'pt-2 border-t border-dashed border-violet-200/80 flex flex-col gap-1.5\';\n                if (levelBadge) levelBadge.className = \'px-2 py-0.5 rounded-md bg-violet-100 text-violet-700\';\n                if (levelXpText) levelXpText.className = \'text-violet-600 font-extrabold\';\n                if (xpText) xpText.className = \'text-violet-500/80 font-bold hidden sm:inline\';\n                if (levelProgressBar) levelProgressBar.className = \'h-full bg-gradient-to-r from-violet-500 to-pink-500 rounded-full transition-all duration-300\';\n                if (levelProgressBg) levelProgressBg.className = \'w-full h-1.5 bg-violet-200/70 rounded-full overflow-hidden transition-colors\';\n            }\n        }\n\n        function getCheckedTasksSummary() {\n            let checkedCount = 0;\n            let mustCount = 0;\n            let taskPoints = 0;\n            const checkedItems = [];\n\n            getEffectiveTasks().forEach(t => {\n                const entry = state.todayChecks[t.id];\n                if (entry && entry.checked) {\n                    checkedCount++;\n                    if (t.group !== \'bonus\') mustCount++;\n                    taskPoints = roundScore(taskPoints + t.points);\n                    checkedItems.push({ ...t, note: entry.note || \'\' });\n                }\n            });\n\n            return { checkedCount, mustCount, taskPoints, checkedItems };\n        }\n\n        function renderAll() {\n            const activeTheme = previewingTheme || state.theme || \'girl\';\n            applyThemeVisuals(activeTheme);\n            const preset = THEME_PRESETS[activeTheme] || THEME_PRESETS.girl;\n\n            document.getElementById(\'student-name-display\').textContent = state.studentName || preset.defaultTitle;\n\n            const childDisplayName = (state.nickname && state.nickname.trim()) || \n                                     (state.studentName && state.studentName.trim() && state.studentName.trim() !== preset.defaultTitle ? state.studentName.trim() : \'\') ||\n                                     (currentSpaceId === \'default\' ? \'个人空间\' : currentSpaceId);\n            document.getElementById(\'space-badge-text\').textContent = childDisplayName;\n            updateSoundButtonVisual();\n\n            const d = new Date();\n            const weekDays = [\'周日\', \'周一\', \'周二\', \'周三\', \'周四\', \'周五\', \'周六\'];\n            document.getElementById(\'current-date-display\').textContent = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日 ${weekDays[d.getDay()]}`;\n\n            animateNumber(\'stat-wallet\', roundScore(state.totalPoints || 0), 300);\n            const xpTextEl = document.getElementById(\'xp-text\');\n            if (xpTextEl) xpTextEl.textContent = `(累计 ${roundScore(state.totalXP || 0)} XP)`;\n            const totalXP = Math.max(0, state.totalXP || 0);\n            const levelIndex = Math.min(preset.levels.length - 1, Math.floor(totalXP / 150));\n            const levelNumber = levelIndex + 1;\n            const isMaxLevel = levelIndex >= preset.levels.length - 1;\n            const currentLevelXP = isMaxLevel ? 150 : (totalXP % 150);\n            const levelPct = isMaxLevel ? 100 : Math.min(100, Math.round((currentLevelXP / 150) * 100));\n\n            const levelBadge = document.getElementById(\'level-badge\');\n            if (levelBadge) {\n                levelBadge.textContent = `Lv.${levelNumber}`;\n                levelBadge.title = `${preset.levels[levelIndex]} (累计经验 ${totalXP} XP)`;\n            }\n            const levelBar = document.getElementById(\'level-progress-bar\');\n            if (levelBar) {\n                levelBar.style.width = `${levelPct}%`;\n            }\n            const levelXpText = document.getElementById(\'level-xp-text\');\n            if (levelXpText) {\n                levelXpText.textContent = isMaxLevel ? \'满级 ✨\' : `${currentLevelXP}/150 XP`;\n            }\n\n            const { checkedCount, mustCount, taskPoints } = getCheckedTasksSummary();\n            const curSpeedPts = getSpecialBonusPoints(\'special_speed\', 1.5);\n            const curNeatPts = getSpecialBonusPoints(\'special_neat\', 1.5);\n            const bonusPoints = roundScore((state.todaySpeedBonus ? curSpeedPts : 0) + (state.todayNeatBonus ? curNeatPts : 0));\n            const previewTotal = roundScore(taskPoints + bonusPoints);\n            animateNumber(\'stat-pending\', previewTotal, 260);\n\n            document.getElementById(\'must-progress-text\').textContent = `${mustCount}/7`;\n            const pct = Math.round((mustCount / 7) * 100);\n            document.getElementById(\'must-progress-pct\').textContent = `${pct}%`;\n            const circumference = 138.2;\n            document.getElementById(\'must-progress-ring\').style.strokeDashoffset = circumference - (pct / 100) * circumference;\n\n            const settledDaysCount = Object.keys(state.dailySettlements || {}).length;\n            document.getElementById(\'stat-streak-text\').textContent = `🔥 已累计打卡 ${settledDaysCount} 天`;\n\n            const todayRecord = state.dailySettlements[state.currentDateKey];\n            const settledBanner = document.getElementById(\'settled-overwrite-banner\');\n            const diffBadge = document.getElementById(\'stat-diff-badge\');\n            const settledSub = document.getElementById(\'stat-settled-sub\');\n            const bottomDiffPill = document.getElementById(\'bottom-bar-diff-pill\');\n            const btnSettleText = document.getElementById(\'btn-settle-text\');\n\n            if (todayRecord) {\n                const prevScore = roundScore(todayRecord.finalScore || 0);\n                const diff = roundScore(previewTotal - prevScore);\n\n                settledBanner.classList.remove(\'hidden\');\n                document.getElementById(\'settled-banner-time\').textContent = `上次提交：${todayRecord.timeStr || \'今日\'} (${prevScore}分 · 第${todayRecord.submitCount || 1}次)`;\n                settledSub.textContent = `上次已入账 ${prevScore} 分 · 以最后一次为准`;\n\n                diffBadge.classList.remove(\'hidden\');\n                diffBadge.textContent = diff === 0 ? \'与上次一致\' : (diff > 0 ? `重算将 +${diff}分` : `重算将 ${diff}分`);\n\n                bottomDiffPill.classList.remove(\'hidden\');\n                bottomDiffPill.textContent = `已入账 ${prevScore} 分 · 差额 ${diff >= 0 ? \'+\' + diff : diff} 分`;\n                btnSettleText.textContent = \'重新覆盖核算\';\n            } else {\n                settledBanner.classList.add(\'hidden\');\n                diffBadge.classList.add(\'hidden\');\n                bottomDiffPill.classList.add(\'hidden\');\n                settledSub.textContent = \'当日以最后一次提交为准\';\n                btnSettleText.textContent = \'家长最终核算\';\n            }\n\n            document.getElementById(\'bottom-bar-summary\').textContent = `今日已勾 ${checkedCount} 项 · 合计 ${previewTotal} 分`;\n\n            renderTaskGrids();\n            renderShop();\n            renderHistory();\n        }\n\n        function renderTaskGrids() {\n            const groups = {\n                school: document.getElementById(\'grid-school\'),\n                selfstudy: document.getElementById(\'grid-selfstudy\'),\n                habit: document.getElementById(\'grid-habit\'),\n                bonus: document.getElementById(\'grid-bonus\')\n            };\n            Object.values(groups).forEach(el => { if (el) el.innerHTML = \'\'; });\n\n            const allTasks = getEffectiveTasks();\n            let schoolTotal = 0;\n            let selfstudyTotal = 0;\n            let habitTotal = 0;\n            let maxBonus = 0;\n\n            allTasks.forEach(t => {\n                if (t.group === \'school\') schoolTotal = roundScore(schoolTotal + t.points);\n                if (t.group === \'selfstudy\') selfstudyTotal = roundScore(selfstudyTotal + t.points);\n                if (t.group === \'habit\') habitTotal = roundScore(habitTotal + t.points);\n                if (t.group === \'bonus\' && t.points > maxBonus) maxBonus = t.points;\n            });\n\n            const pSchool = document.getElementById(\'group-pill-school\');\n            if (pSchool) pSchool.textContent = `基础必做 · 共 ${schoolTotal} 分`;\n            const pSelfstudy = document.getElementById(\'group-pill-selfstudy\');\n            if (pSelfstudy) pSelfstudy.textContent = `拔高必做 · 共 ${selfstudyTotal} 分`;\n            const pHabit = document.getElementById(\'group-pill-habit\');\n            if (pHabit) pHabit.textContent = `习惯必做 · +${habitTotal} 分`;\n            const pBonus = document.getElementById(\'group-pill-bonus\');\n            if (pBonus) pBonus.textContent = `进阶大挑战 · 最高 +${maxBonus} 分`;\n\n            const colorStyles = {\n                sky: {\n                    unchecked: \'bg-white border border-sky-200/90 border-b-4 border-b-sky-300 hover:border-sky-300 hover:border-b-sky-400\',\n                    checked: \'bg-gradient-to-br from-emerald-50 to-teal-50/75 border border-emerald-300 border-b-4 border-b-emerald-500 shadow-pastel-mint\',\n                    iconBox: \'bg-sky-100 text-sky-600 border border-sky-200\',\n                    badge: \'bg-sky-50 text-sky-700 border border-sky-200\'\n                },\n                sakura: {\n                    unchecked: \'bg-white border border-pink-200/90 border-b-4 border-b-pink-300 hover:border-pink-300 hover:border-b-pink-400\',\n                    checked: \'bg-gradient-to-br from-emerald-50 to-teal-50/75 border border-emerald-300 border-b-4 border-b-emerald-500 shadow-pastel-mint\',\n                    iconBox: \'bg-pink-100 text-pink-600 border border-pink-200\',\n                    badge: \'bg-pink-50 text-pink-700 border border-pink-200\'\n                },\n                lavender: {\n                    unchecked: \'bg-white border border-violet-200/90 border-b-4 border-b-violet-300 hover:border-violet-300 hover:border-b-violet-400\',\n                    checked: \'bg-gradient-to-br from-emerald-50 to-teal-50/75 border border-emerald-300 border-b-4 border-b-emerald-500 shadow-pastel-mint\',\n                    iconBox: \'bg-violet-100 text-violet-600 border border-violet-200\',\n                    badge: \'bg-violet-50 text-violet-700 border border-violet-200\'\n                },\n                mint: {\n                    unchecked: \'bg-white border border-emerald-200/90 border-b-4 border-b-emerald-300 hover:border-emerald-300 hover:border-b-emerald-400\',\n                    checked: \'bg-gradient-to-br from-emerald-50 to-teal-50/85 border border-emerald-300 border-b-4 border-b-emerald-500 shadow-pastel-mint\',\n                    iconBox: \'bg-emerald-100 text-emerald-600 border border-emerald-200\',\n                    badge: \'bg-emerald-50 text-emerald-700 border border-emerald-200\'\n                },\n                butter: {\n                    unchecked: \'bg-white border border-amber-200/90 border-b-4 border-b-amber-300 hover:border-amber-300 hover:border-b-amber-400\',\n                    checked: \'bg-gradient-to-br from-amber-50 via-yellow-50 to-orange-50/60 border border-amber-300 border-b-4 border-b-amber-500 shadow-pastel-butter\',\n                    iconBox: \'bg-amber-100 text-amber-600 border border-amber-200\',\n                    badge: \'bg-amber-100 text-amber-800 border border-amber-300\'\n                }\n            };\n\n            allTasks.forEach(task => {\n                const container = groups[task.group];\n                if (!container) return;\n                const entry = state.todayChecks[task.id] || { checked: false, note: \'\' };\n                const isChecked = !!entry.checked;\n                const st = colorStyles[task.color] || colorStyles.lavender;\n                const isThreeColGroup = task.group === \'school\' || task.group === \'selfstudy\';\n\n                const card = document.createElement(\'div\');\n                card.className = `card-3d-press cursor-pointer rounded-[26px] p-4 transition-all h-full flex flex-col justify-between ${isThreeColGroup ? \'min-h-[116px]\' : \'min-h-[92px]\'} ${isChecked ? st.checked : st.unchecked}`;\n                card.onclick = (e) => handleTaskClick(task.id, e);\n\n                const checkIconHtml = `<svg class="w-5 h-5 text-white animate-check-svg shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>`;\n\n                const noteBadgeHtml = entry.note\n                    ? `<div class="mt-2 text-xs font-extrabold text-amber-800 bg-amber-100/80 border border-amber-300/80 rounded-xl px-2.5 py-1 truncate">📌 成果：${escapeHtml(entry.note)}</div>`\n                    : \'\';\n\n                if (isThreeColGroup) {\n                    card.innerHTML = `\n                        <div class="flex items-center justify-between gap-2">\n                            <div class="flex items-center gap-2.5 min-w-0">\n                                <div class="w-10 h-10 rounded-2xl ${isChecked ? \'bg-emerald-500 text-white border-emerald-400\' : st.iconBox} border flex items-center justify-center text-lg shrink-0 transition-colors shadow-2xs">\n                                    ${isChecked ? checkIconHtml : task.icon}\n                                </div>\n                                <h3 class="font-black text-sm sm:text-[15px] ${isChecked ? \'text-emerald-950\' : \'text-[#2E2545]\'} truncate leading-tight">${escapeHtml(task.title)}</h3>\n                            </div>\n                            <span class="px-2.5 py-0.5 rounded-full text-[11px] font-black border shrink-0 ${isChecked ? \'bg-emerald-500 text-white border-emerald-500\' : st.badge}">\n                                +${task.points}分\n                            </span>\n                        </div>\n                        <p class="text-xs font-bold text-[#7E7494] mt-2.5 leading-relaxed line-clamp-2">${escapeHtml(task.desc)}</p>\n                    `;\n                } else {\n                    card.innerHTML = `\n                        <div class="flex items-start justify-between gap-3 my-auto">\n                            <div class="flex items-start gap-3 min-w-0">\n                                <div class="w-11 h-11 rounded-2xl ${isChecked ? \'bg-emerald-500 text-white border-emerald-400\' : st.iconBox} border flex items-center justify-center text-xl shrink-0 transition-colors">\n                                    ${isChecked ? checkIconHtml : task.icon}\n                                </div>\n                                <div class="min-w-0">\n                                    <h3 class="font-black text-sm sm:text-base ${isChecked ? \'text-emerald-950\' : \'text-[#2E2545]\'} leading-snug">${escapeHtml(task.title)}</h3>\n                                    <p class="text-xs font-bold text-[#7E7494] mt-0.5 leading-relaxed">${escapeHtml(task.desc)}</p>\n                                    ${noteBadgeHtml}\n                                </div>\n                            </div>\n                            <span class="px-2.5 py-1 rounded-full text-xs font-black border shrink-0 ${isChecked ? \'bg-emerald-500 text-white border-emerald-500\' : st.badge}">\n                                +${task.points}分\n                            </span>\n                        </div>\n                    `;\n                }\n                container.appendChild(card);\n            });\n        }\n\n        function handleTaskClick(taskId, event) {\n            const rawTask = TASKS.find(t => t.id === taskId);\n            if (!rawTask) return;\n            const task = { ...rawTask, points: getTaskPoints(rawTask) };\n            const entry = state.todayChecks[taskId] || { checked: false, note: \'\' };\n\n            if (task.group === \'bonus\' && !entry.checked) {\n                currentBonusTaskId = taskId;\n                document.getElementById(\'bonus-modal-icon\').textContent = task.icon;\n                document.getElementById(\'bonus-modal-title\').textContent = task.title;\n                document.getElementById(\'bonus-modal-subtitle\').textContent = `🌟 进阶悬赏挑战 · +${task.points} 分`;\n                document.getElementById(\'bonus-modal-confirm-btn\').textContent = `🌟 完成打卡 (+${task.points}分)`;\n                document.getElementById(\'bonus-modal-label\').textContent = task.prompt || \'写下今天完成的挑战成果吧（选填）：\';\n                document.getElementById(\'bonus-note-input\').value = entry.note || \'\';\n                openModal(\'modal-bonus-note\');\n                setTimeout(() => document.getElementById(\'bonus-note-input\').focus(), 100);\n                return;\n            }\n\n            entry.checked = !entry.checked;\n            if (!entry.checked) entry.note = \'\';\n            state.todayChecks[taskId] = entry;\n            saveState();\n\n            if (entry.checked) {\n                playSound(\'check\');\n                const { mustCount } = getCheckedTasksSummary();\n                if (mustCount === 7 && task.group !== \'bonus\') {\n                    playSound(\'fanfare\');\n                    fireConfetti(60);\n                    showToast(\'🎉 太棒啦！今日 7 项必做任务全部通关！\');\n                } else {\n                    const clickX = event && event.clientX ? event.clientX : window.innerWidth / 2;\n                    const clickY = event && event.clientY ? event.clientY : window.innerHeight / 2;\n                    fireMicroConfetti(clickX, clickY);\n                }\n            } else {\n                playSound(\'uncheck\');\n            }\n            renderAll();\n        }\n\n        function confirmBonusTask() {\n            if (!currentBonusTaskId) return;\n            const rawTask = TASKS.find(t => t.id === currentBonusTaskId);\n            const pts = rawTask ? getTaskPoints(rawTask) : 15;\n            const noteVal = document.getElementById(\'bonus-note-input\').value.trim();\n            state.todayChecks[currentBonusTaskId] = {\n                checked: true,\n                note: noteVal\n            };\n            saveState();\n            closeModal(\'modal-bonus-note\');\n            playSound(\'fanfare\');\n            fireConfetti(45);\n            renderAll();\n            showToast(`🌟 进阶大挑战打卡成功 (+${pts}分)！`);\n        }\n\n        function openSettlementModal() {\n            document.getElementById(\'parent-speed-bonus\').checked = !!state.todaySpeedBonus;\n            document.getElementById(\'parent-neat-bonus\').checked = !!state.todayNeatBonus;\n            document.getElementById(\'settlement-pin\').value = \'\';\n            document.getElementById(\'settlement-error\').classList.add(\'hidden\');\n\n            const sBadge = document.getElementById(\'settle-speed-pts-badge\');\n            if (sBadge) sBadge.textContent = \'+\' + getSpecialBonusPoints(\'special_speed\', 1.5) + \' 分\';\n            const nBadge = document.getElementById(\'settle-neat-pts-badge\');\n            if (nBadge) nBadge.textContent = \'+\' + getSpecialBonusPoints(\'special_neat\', 1.5) + \' 分\';\n\n            updateSettlementTotalPreview();\n            openModal(\'modal-settlement\');\n        }\n\n        function updateSettlementTotalPreview() {\n            const { checkedItems, taskPoints } = getCheckedTasksSummary();\n            const speedBonus = document.getElementById(\'parent-speed-bonus\').checked;\n            const neatBonus = document.getElementById(\'parent-neat-bonus\').checked;\n            const curSpeed = getSpecialBonusPoints(\'special_speed\', 1.5);\n            const curNeat = getSpecialBonusPoints(\'special_neat\', 1.5);\n            const finalScore = roundScore(taskPoints + (speedBonus ? curSpeed : 0) + (neatBonus ? curNeat : 0));\n\n            document.getElementById(\'modal-pending-count\').textContent = `已选 ${checkedItems.length} 项`;\n            const listEl = document.getElementById(\'modal-task-list\');\n            if (checkedItems.length === 0) {\n                listEl.innerHTML = `<p class="text-xs font-bold text-[#7E7494] text-center py-3">今日暂未勾选任何任务（如以 0 分提交将退回今日已入账积分）</p>`;\n            } else {\n                listEl.innerHTML = checkedItems.map(item => `\n                    <div class="flex items-center justify-between text-xs font-bold text-[#2E2545] bg-white px-3 py-2 rounded-xl border border-violet-100">\n                        <span class="truncate">${item.icon} ${escapeHtml(item.title)} ${item.note ? `<span class="text-amber-700">(${escapeHtml(item.note)})</span>` : \'\'}</span>\n                        <span class="font-black text-violet-700 shrink-0">+${item.points}分</span>\n                    </div>\n                `).join(\'\');\n            }\n\n            document.getElementById(\'modal-total-score\').textContent = `${finalScore} 分`;\n\n            const todayRecord = state.dailySettlements[state.currentDateKey];\n            const badgeEl = document.getElementById(\'modal-settle-badge\');\n            const alertBox = document.getElementById(\'modal-overwrite-alert\');\n            const detailEl = document.getElementById(\'modal-overwrite-detail\');\n            const netDiffEl = document.getElementById(\'modal-net-diff\');\n\n            if (todayRecord) {\n                const prevScore = roundScore(todayRecord.finalScore || 0);\n                const diff = roundScore(finalScore - prevScore);\n                const nextCount = (todayRecord.submitCount || 1) + 1;\n\n                badgeEl.textContent = `第 ${nextCount} 次提交覆盖`;\n                badgeEl.className = \'text-[11px] font-extrabold px-2.5 py-0.5 rounded-full bg-emerald-100 text-emerald-800\';\n                alertBox.classList.remove(\'hidden\');\n                detailEl.innerHTML = `今日上次已入账 <b>${prevScore} 分</b> → 本次最终覆盖为 <b>${finalScore} 分</b>。<br>系统将自动按最后一次提交冲抵差额，总积分净变动：<b>${diff >= 0 ? \'+\' + diff : diff} 分</b>。`;\n\n                netDiffEl.classList.remove(\'hidden\');\n                netDiffEl.textContent = `净变动 ${diff >= 0 ? \'+\' + diff : diff} 分`;\n                netDiffEl.className = `text-xs font-extrabold px-2 py-0.5 rounded-full ${diff >= 0 ? \'bg-emerald-100 text-emerald-800\' : \'bg-rose-100 text-rose-700\'}`;\n            } else {\n                badgeEl.textContent = \'今日首次提交\';\n                badgeEl.className = \'text-[11px] font-extrabold px-2.5 py-0.5 rounded-full bg-violet-100 text-violet-700\';\n                alertBox.classList.add(\'hidden\');\n                netDiffEl.classList.add(\'hidden\');\n            }\n        }\n\n        function confirmSettlement() {\n            const pinInput = document.getElementById(\'settlement-pin\').value.trim();\n            const errEl = document.getElementById(\'settlement-error\');\n            if (pinInput !== state.pin) {\n                errEl.textContent = \'❌ 家长 PIN 码不正确（初始默认为 1234）\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            const speedBonus = document.getElementById(\'parent-speed-bonus\').checked;\n            const neatBonus = document.getElementById(\'parent-neat-bonus\').checked;\n            state.todaySpeedBonus = speedBonus;\n            state.todayNeatBonus = neatBonus;\n\n            const { checkedItems, taskPoints } = getCheckedTasksSummary();\n            const curSpeed = getSpecialBonusPoints(\'special_speed\', 1.5);\n            const curNeat = getSpecialBonusPoints(\'special_neat\', 1.5);\n            const finalScore = roundScore(taskPoints + (speedBonus ? curSpeed : 0) + (neatBonus ? curNeat : 0));\n\n            const dateKey = state.currentDateKey;\n            const prevRecord = state.dailySettlements[dateKey];\n            const prevScore = prevRecord ? roundScore(prevRecord.finalScore || 0) : 0;\n            const diff = roundScore(finalScore - prevScore);\n            const submitCount = prevRecord ? ((prevRecord.submitCount || 1) + 1) : 1;\n\n            const now = new Date();\n            const timeStr = `${String(now.getHours()).padStart(2, \'0\')}:${String(now.getMinutes()).padStart(2, \'0\')}`;\n\n            state.totalPoints = Math.max(0, roundScore((state.totalPoints || 0) + diff));\n            state.totalXP = Math.max(0, roundScore((state.totalXP || 0) + diff));\n\n            state.dailySettlements[dateKey] = {\n                dateKey,\n                finalScore,\n                submitCount,\n                timeStr,\n                speedBonus,\n                neatBonus,\n                checksSnapshot: JSON.parse(JSON.stringify(state.todayChecks))\n            };\n\n            const detailParts = checkedItems.map(i => i.note ? `${i.title}(${i.note})` : i.title);\n            if (speedBonus) detailParts.push(`🚀高效不拖拉(+${curSpeed})`);\n            if (neatBonus) detailParts.push(`✍️书写工整(+${curNeat})`);\n\n            const ledgerEntry = {\n                id: `settle_${dateKey}`,\n                dateKey,\n                type: \'settlement\',\n                title: submitCount > 1\n                    ? `${dateKey} 每日最终核算（第 ${submitCount} 次提交覆盖 · 以此为准）`\n                    : `${dateKey} 每日最终核算入账`,\n                desc: detailParts.length > 0 ? detailParts.join(\'、\') : \'当日0分覆盖核算\',\n                points: finalScore,\n                time: `${dateKey} ${timeStr}`\n            };\n\n            const existingIdx = state.history.findIndex(h => h.type === \'settlement\' && h.dateKey === dateKey);\n            if (existingIdx !== -1) {\n                state.history[existingIdx] = ledgerEntry;\n            } else {\n                state.history.unshift(ledgerEntry);\n            }\n\n            saveState();\n            closeModal(\'modal-settlement\');\n            playSound(\'fanfare\');\n            fireConfetti(80);\n            renderAll();\n\n            if (submitCount > 1) {\n                showToast(`✅ 已按最后一次提交覆盖！今日最终得分：${finalScore} 分（净变动 ${diff >= 0 ? \'+\' + diff : diff} 分）`);\n            } else {\n                showToast(`🎉 核算成功！今日入账 +${finalScore} 分！`);\n            }\n        }\n\n        function renderShop() {\n            const grid = document.getElementById(\'shop-grid\');\n            if (!grid) return;\n            grid.innerHTML = \'\';\n\n            const activeTheme = previewingTheme || state.theme || \'girl\';\n            const isBoy = activeTheme === \'boy\';\n            const currentPts = Math.max(0, state.totalPoints || 0);\n\n            state.rewards.forEach(rw => {\n                const canAfford = currentPts >= rw.cost;\n                const diff = Math.max(0, rw.cost - currentPts);\n                const pct = rw.cost > 0 ? Math.min(99, Math.round((currentPts / rw.cost) * 100)) : 100;\n\n                const card = document.createElement(\'div\');\n                const cardBorderClass = isBoy \n                    ? \'border-blue-100 border-b-blue-200 hover:border-blue-200 hover:border-b-blue-300\' \n                    : \'border-violet-100 border-b-violet-200 hover:border-violet-200 hover:border-b-violet-300\';\n                const iconBgClass = isBoy ? \'bg-blue-50 border-blue-200\' : \'bg-pink-50 border-pink-200\';\n                const costClass = isBoy ? \'text-blue-600\' : \'text-pink-600\';\n                const unaffordBtnClass = isBoy ? \'bg-blue-50 text-blue-700 border-blue-200/80\' : \'bg-pink-50 text-pink-700 border-pink-200/80\';\n                const progressTrackClass = isBoy ? \'bg-blue-100/70\' : \'bg-pink-100/70\';\n                const progressBarClass = isBoy ? \'bg-gradient-to-r from-blue-500 to-cyan-400\' : \'bg-gradient-to-r from-pink-400 to-rose-400\';\n                const progressTextClass = isBoy ? \'text-blue-600\' : \'text-pink-600\';\n\n                card.className = `card-3d-press bg-white/95 rounded-[26px] p-4 border border-b-4 ${cardBorderClass} shadow-pastel-sm flex flex-col justify-between gap-3`;\n                card.innerHTML = `\n                    <div class="flex items-center justify-between gap-3">\n                        <div class="flex items-center gap-3.5 min-w-0">\n                            <div class="w-12 h-12 rounded-2xl ${iconBgClass} border flex items-center justify-center text-2xl shrink-0">\n                                ${escapeHtml(rw.icon || \'🎁\')}\n                            </div>\n                            <div class="min-w-0">\n                                <h4 class="font-black text-sm sm:text-base text-[#2E2545] truncate">${escapeHtml(rw.title)}</h4>\n                                <span class="text-xs font-extrabold ${costClass}">💎 ${rw.cost} 积分</span>\n                            </div>\n                        </div>\n                        <button onclick="redeemReward(\'${rw.id}\')" class="px-3.5 py-2 rounded-2xl font-extrabold text-xs shrink-0 transition ${canAfford ? \'theme-primary-bg text-white shadow-xs hover:opacity-95 cursor-pointer\' : `${unaffordBtnClass} border cursor-not-allowed`}">\n                            ${canAfford ? \'✨ 立即兑换\' : `还差 ${diff} 分`}\n                        </button>\n                    </div>\n                    ${!canAfford ? `\n                    <div class="pt-2.5 border-t border-dashed ${isBoy ? \'border-blue-100/90\' : \'border-pink-100/90\'}">\n                        <div class="flex items-center justify-between text-[11px] font-bold mb-1">\n                            <span class="${progressTextClass} font-extrabold flex items-center gap-1">\n                                <span>🎯</span>\n                                <span>心愿蓄力中</span>\n                            </span>\n                            <span class="text-[#7E7494] font-bold">已达成 <span class="${progressTextClass} font-black">${pct}%</span> · 还差 <span class="${progressTextClass} font-black">${diff}</span> 分</span>\n                        </div>\n                        <div class="w-full h-1.5 ${progressTrackClass} rounded-full overflow-hidden">\n                            <div class="h-full ${progressBarClass} rounded-full transition-all duration-300" style="width: ${pct}%"></div>\n                        </div>\n                    </div>\n                    ` : \'\'}\n                `;\n                grid.appendChild(card);\n            });\n        }\n\n        function redeemReward(rewardId) {\n            const rw = state.rewards.find(r => r.id === rewardId);\n            if (!rw) return;\n            if (state.totalPoints < rw.cost) {\n                showToast(\'⚠️ 当前可用积分不足，继续打卡攒分吧！\');\n                return;\n            }\n            state.totalPoints = roundScore(state.totalPoints - rw.cost);\n            const now = new Date();\n            const timeStr = `${state.currentDateKey} ${String(now.getHours()).padStart(2, \'0\')}:${String(now.getMinutes()).padStart(2, \'0\')}`;\n            state.history.unshift({\n                id: \'redeem_\' + Date.now(),\n                type: \'redeem\',\n                title: `兑换心愿：${rw.title}`,\n                desc: \'积分商城心愿达成\',\n                points: -rw.cost,\n                time: timeStr\n            });\n            saveState();\n            playSound(\'fanfare\');\n            fireConfetti(50);\n            renderAll();\n            showToast(`🎁 成功兑换「${rw.title}」！`);\n        }\n\n        function updateAddTitleCount() {\n            const el = document.getElementById(\'reward-title-input\');\n            const countEl = document.getElementById(\'reward-title-count\');\n            if (el && countEl) {\n                const len = el.value.length;\n                countEl.textContent = `${len}/14字`;\n                countEl.className = len >= 15 ? \'text-[11px] font-bold text-rose-500\' : \'text-[11px] font-bold text-violet-500\';\n            }\n        }\n\n        function updateEditTitleCount() {\n            const el = document.getElementById(\'edit-reward-title-input\');\n            const countEl = document.getElementById(\'edit-reward-title-count\');\n            if (el && countEl) {\n                const len = el.value.length;\n                countEl.textContent = `${len}/14字`;\n                countEl.className = len >= 15 ? \'text-[11px] font-bold text-rose-500\' : \'text-[11px] font-bold text-violet-500\';\n            }\n        }\n\n        function openAddRewardModal() {\n            document.getElementById(\'reward-title-input\').value = \'\';\n            document.getElementById(\'reward-cost-input\').value = \'50\';\n            document.getElementById(\'reward-pin-input\').value = \'\';\n            document.getElementById(\'reward-error\').classList.add(\'hidden\');\n            updateAddTitleCount();\n            openModal(\'modal-add-reward\');\n        }\n\n        function saveNewReward() {\n            const icon = document.getElementById(\'reward-icon-input\').value.trim() || \'🎁\';\n            const title = document.getElementById(\'reward-title-input\').value.trim();\n            const cost = parseInt(document.getElementById(\'reward-cost-input\').value, 10);\n            const pin = document.getElementById(\'reward-pin-input\').value.trim();\n            const errEl = document.getElementById(\'reward-error\');\n\n            if (!title) {\n                errEl.textContent = \'❌ 请输入心愿名称\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (title.length >= 15) {\n                errEl.textContent = `❌ 心愿描述必须少于15个字（不含15，当前 ${title.length} 字）`;\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (isNaN(cost) || cost <= 0) {\n                errEl.textContent = \'❌ 所需积分必须为大于0的整数\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (pin !== state.pin) {\n                errEl.textContent = \'❌ 家长 PIN 码不正确\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            state.rewards.push({ id: \'rw_\' + Date.now(), title, cost, icon });\n            saveState();\n            closeModal(\'modal-add-reward\');\n            renderAll();\n            showToast(\'🎁 新心愿奖品已上架！\');\n        }\n\n        function renderManageRewardsList() {\n            const listEl = document.getElementById(\'manage-rewards-list\');\n            if (!listEl) return;\n            if (!state.rewards || state.rewards.length === 0) {\n                listEl.innerHTML = \'<div class="text-center py-6 text-xs font-bold text-[#7E7494]">暂无可调整的心愿奖品</div>\';\n                return;\n            }\n            listEl.innerHTML = state.rewards.map(rw => `\n                <div class="flex items-center justify-between gap-3 p-3 rounded-2xl bg-[#FAF8FF] border border-violet-100">\n                    <div class="flex items-center gap-2.5 min-w-0">\n                        <span class="text-xl shrink-0">${escapeHtml(rw.icon || \'🎁\')}</span>\n                        <div class="min-w-0">\n                            <p class="font-black text-xs text-[#2E2545] truncate">${escapeHtml(rw.title)}</p>\n                            <span class="text-[11px] font-extrabold text-pink-600">💎 ${rw.cost} 积分</span>\n                        </div>\n                    </div>\n                    <button onclick="startEditRewardFromManage(\'${rw.id}\')" class="px-3 py-1.5 rounded-xl bg-violet-100 hover:bg-violet-200 text-violet-800 font-black text-xs transition shrink-0">\n                        ✏️ 调整\n                    </button>\n                </div>\n            `).join(\'\');\n        }\n\n        function openManageRewardsModal() {\n            renderManageRewardsList();\n            openModal(\'modal-manage-rewards\');\n        }\n\n        function startEditRewardFromManage(rewardId) {\n            closeModal(\'modal-manage-rewards\');\n            openEditRewardModal(rewardId);\n        }\n\n        function openEditRewardModal(rewardId) {\n            const rw = state.rewards.find(r => r.id === rewardId);\n            if (!rw) {\n                showToast(\'❌ 未找到该心愿\');\n                return;\n            }\n            document.getElementById(\'edit-reward-id\').value = rw.id;\n            document.getElementById(\'edit-reward-icon-input\').value = rw.icon || \'🎁\';\n            document.getElementById(\'edit-reward-title-input\').value = rw.title || \'\';\n            document.getElementById(\'edit-reward-cost-input\').value = rw.cost || 50;\n            document.getElementById(\'edit-reward-pin-input\').value = \'\';\n            document.getElementById(\'edit-reward-error\').classList.add(\'hidden\');\n            updateEditTitleCount();\n            openModal(\'modal-edit-reward\');\n        }\n\n        function submitEditReward() {\n            const rewardId = document.getElementById(\'edit-reward-id\').value;\n            const rw = state.rewards.find(r => r.id === rewardId);\n            const errEl = document.getElementById(\'edit-reward-error\');\n\n            if (!rw) {\n                errEl.textContent = \'❌ 未找到该心愿记录\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            const icon = document.getElementById(\'edit-reward-icon-input\').value.trim() || \'🎁\';\n            const title = document.getElementById(\'edit-reward-title-input\').value.trim();\n            const cost = parseInt(document.getElementById(\'edit-reward-cost-input\').value, 10);\n            const pin = document.getElementById(\'edit-reward-pin-input\').value.trim();\n\n            if (!title) {\n                errEl.textContent = \'❌ 心愿描述不能为空\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (title.length >= 15) {\n                errEl.textContent = `❌ 心愿描述必须少于15个字（不含15，当前 ${title.length} 字）`;\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (isNaN(cost) || cost <= 0) {\n                errEl.textContent = \'❌ 所需积分必须为大于0的整数\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (pin !== state.pin) {\n                errEl.textContent = \'❌ 家长 PIN 码不正确\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            rw.title = title;\n            rw.cost = cost;\n            rw.icon = icon;\n\n            saveState();\n            closeModal(\'modal-edit-reward\');\n            renderAll();\n            showToast(`✏️ 已成功调整心愿「${title}」及积分！`);\n        }\n\n        function renderHistory() {\n            const listEl = document.getElementById(\'history-list\');\n            const countEl = document.getElementById(\'history-count\');\n            if (!listEl) return;\n\n            countEl.textContent = `共 ${state.history.length} 条记录`;\n            if (state.history.length === 0) {\n                listEl.innerHTML = `<div class="text-center py-8 text-xs font-bold text-[#7E7494]">暂无账本记录，完成今日打卡并由家长核算后将在此显示 ✨</div>`;\n                return;\n            }\n\n            listEl.innerHTML = state.history.map(item => {\n                const isPos = item.points >= 0;\n                return `\n                    <div class="flex items-center justify-between gap-3 p-3.5 rounded-2xl bg-[#FAF8FF] border border-violet-100">\n                        <div class="min-w-0">\n                            <div class="flex items-center gap-2 flex-wrap">\n                                <span class="font-black text-xs sm:text-sm text-[#2E2545]">${escapeHtml(item.title)}</span>\n                                <span class="text-[11px] font-bold text-[#7E7494]">${escapeHtml(item.time || \'\')}</span>\n                            </div>\n                            <p class="text-xs font-bold text-[#6E6385] mt-0.5 truncate">${escapeHtml(item.desc || \'\')}</p>\n                        </div>\n                        <span class="font-black text-sm sm:text-base shrink-0 ${isPos ? \'text-emerald-600\' : \'text-rose-500\'}">\n                            ${isPos ? \'+\' + item.points : item.points} 分\n                        </span>\n                    </div>\n                `;\n            }).join(\'\');\n        }\n\n        function openManualAdjustModal() {\n            document.getElementById(\'adjust-points-input\').value = \'2\';\n            document.getElementById(\'adjust-reason-input\').value = \'\';\n            document.getElementById(\'adjust-pin-input\').value = \'\';\n            document.getElementById(\'adjust-error\').classList.add(\'hidden\');\n            openModal(\'modal-manual-adjust\');\n        }\n\n        function confirmManualAdjust() {\n            const pts = roundScore(parseFloat(document.getElementById(\'adjust-points-input\').value) || 0);\n            const reason = document.getElementById(\'adjust-reason-input\').value.trim() || \'家长手动调整\';\n            const pin = document.getElementById(\'adjust-pin-input\').value.trim();\n            const errEl = document.getElementById(\'adjust-error\');\n\n            if (pin !== state.pin) {\n                errEl.textContent = \'❌ 家长 PIN 码不正确\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (pts === 0) {\n                errEl.textContent = \'❌ 调整分值不能为 0\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            state.totalPoints = Math.max(0, roundScore(state.totalPoints + pts));\n            if (pts > 0) state.totalXP = roundScore((state.totalXP || 0) + pts);\n\n            const now = new Date();\n            const timeStr = `${state.currentDateKey} ${String(now.getHours()).padStart(2, \'0\')}:${String(now.getMinutes()).padStart(2, \'0\')}`;\n            state.history.unshift({\n                id: \'adj_\' + Date.now(),\n                type: \'adjust\',\n                title: pts > 0 ? \'家长手动奖励加分\' : \'家长手动扣分调整\',\n                desc: reason,\n                points: pts,\n                time: timeStr\n            });\n\n            saveState();\n            closeModal(\'modal-manual-adjust\');\n            renderAll();\n            showToast(`⚡ 已完成积分调整 (${pts > 0 ? \'+\' + pts : pts} 分)`);\n        }\n\n        function openSettingsModal() {\n            previewingTheme = state.theme || \'girl\';\n            updateThemeSelectorCards(previewingTheme);\n            updateSoundButtonVisual();\n            document.getElementById(\'set-child-nickname\').value = state.nickname || \'\';\n            document.getElementById(\'set-child-name\').value = state.studentName || THEME_PRESETS[previewingTheme].defaultTitle;\n            document.getElementById(\'set-old-pin\').value = \'\';\n            document.getElementById(\'set-new-pin\').value = \'\';\n            document.getElementById(\'settings-msg\').classList.add(\'hidden\');\n            openModal(\'modal-settings\');\n        }\n\n        function previewThemeSelection(themeKey) {\n            previewingTheme = themeKey;\n            updateThemeSelectorCards(themeKey);\n            const nameInput = document.getElementById(\'set-child-name\');\n            const currentVal = nameInput.value.trim();\n            if (!currentVal || currentVal === THEME_PRESETS.girl.defaultTitle || currentVal === THEME_PRESETS.boy.defaultTitle) {\n                nameInput.value = THEME_PRESETS[themeKey].defaultTitle;\n            }\n            applyThemeVisuals(themeKey);\n            renderShop();\n        }\n\n        function updateThemeSelectorCards(themeKey) {\n            const girlBtn = document.getElementById(\'theme-card-girl\');\n            const boyBtn = document.getElementById(\'theme-card-boy\');\n            if (themeKey === \'boy\') {\n                boyBtn.className = \'p-3.5 rounded-2xl border-2 text-left transition-all flex items-center gap-3 cursor-pointer bg-[#F4F9FF] border-blue-500 ring-2 ring-blue-200\';\n                girlBtn.className = \'p-3.5 rounded-2xl border-2 text-left transition-all flex items-center gap-3 cursor-pointer bg-[#FAF8FF] border-violet-200 hover:border-violet-400\';\n            } else {\n                girlBtn.className = \'p-3.5 rounded-2xl border-2 text-left transition-all flex items-center gap-3 cursor-pointer bg-[#FAF8FF] border-[#8B7CF6] ring-2 ring-violet-200\';\n                boyBtn.className = \'p-3.5 rounded-2xl border-2 text-left transition-all flex items-center gap-3 cursor-pointer bg-[#F4F9FF] border-sky-200 hover:border-sky-400\';\n            }\n        }\n\n        function cancelSettingsModal() {\n            previewingTheme = null;\n            closeModal(\'modal-settings\');\n            renderAll();\n        }\n\n        function saveSettings() {\n            const oldPin = document.getElementById(\'set-old-pin\').value.trim();\n            const newPin = document.getElementById(\'set-new-pin\').value.trim();\n            const msgEl = document.getElementById(\'settings-msg\');\n\n            if (oldPin !== state.pin) {\n                msgEl.textContent = \'❌ 请输入正确的当前家长 PIN 码（初始默认为 1234）\';\n                msgEl.classList.remove(\'hidden\');\n                return;\n            }\n            if (newPin && !/^\\d{4}$/.test(newPin)) {\n                msgEl.textContent = \'❌ 新 PIN 码必须是 4 位数字\';\n                msgEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            state.theme = previewingTheme || state.theme || \'girl\';\n            previewingTheme = null;\n            state.nickname = document.getElementById(\'set-child-nickname\').value.trim();\n            state.studentName = document.getElementById(\'set-child-name\').value.trim() || THEME_PRESETS[state.theme].defaultTitle;\n            if (newPin) state.pin = newPin;\n\n            saveState();\n            closeModal(\'modal-settings\');\n            renderAll();\n            showToast(\'⚙️ 设置与主题已保存生效！\');\n        }\n\n        function openTaskPointsModal() {\n            const container = document.getElementById(\'task-points-list\');\n            if (!container) return;\n\n            const currentPts = state.customTaskPoints || {};\n            const groups = [\n                { id: \'school\', title: \'🎒 每日必做 · 校内基础清零\', desc: \'数学、语文、英语基础项（默认每项 1 分）\' },\n                { id: \'selfstudy\', title: \'📖 每日自学 · 习惯养成\', desc: \'英语、数学、语文自律拓展（默认每项 2 分）\' },\n                { id: \'habit\', title: \'🌟 个人生活与好习惯\', desc: \'日常好习惯自律（默认 0.5 分）\' },\n                { id: \'bonus\', title: \'🏆 进阶大挑战 · 额外激励\', desc: \'完整读完一本书（默认 150 分）、高阶学科攻坚（默认 15 分）\' },\n                { id: \'settle_bonus\', title: \'⭐ 家长晚间复核 · 专属特权加成\', desc: \'高效不拖拉早鸟奖与卷面书写工整奖（默认每项 1.5 分）\' }\n            ];\n\n            const allItems = getAllConfigurableItems();\n            let html = \'\';\n            groups.forEach(g => {\n                const groupItems = allItems.filter(t => t.group === g.id);\n                if (groupItems.length === 0) return;\n\n                html += \'<div class="pt-3.5 first:pt-0">\' +\n                    \'<div class="mb-2">\' +\n                        \'<span class="text-xs font-black text-[#2E2545] tracking-wide">\' + g.title + \'</span>\' +\n                        \'<span class="text-[10px] font-bold text-[#7E7494] ml-1.5">\' + g.desc + \'</span>\' +\n                    \'</div>\' +\n                    \'<div class="grid grid-cols-1 sm:grid-cols-2 gap-2">\';\n\n                groupItems.forEach(item => {\n                    const val = currentPts[item.id] !== undefined ? currentPts[item.id] : item.points;\n                    const itemTitle = item.title || \'未命名项目\';\n                    const itemDesc = item.desc || \'\';\n                    html += \'<div class="flex items-center justify-between p-2.5 rounded-2xl bg-slate-50 border border-slate-100 hover:border-amber-200 transition gap-2.5">\' +\n                        \'<div class="flex items-center gap-2.5 min-w-0 pr-1">\' +\n                            \'<span class="text-lg shrink-0">\' + item.icon + \'</span>\' +\n                            \'<div class="min-w-0">\' +\n                                \'<p class="text-xs font-black text-[#2E2545] truncate">\' + itemTitle + \'</p>\' +\n                                (itemDesc ? \'<p class="text-[10px] font-bold text-[#7E7494] truncate">\' + itemDesc + \'</p>\' : \'\') +\n                            \'</div>\' +\n                        \'</div>\' +\n                        \'<div class="flex items-center gap-1 shrink-0">\' +\n                            \'<span class="text-xs font-extrabold text-amber-600">+</span>\' +\n                            \'<input type="number" step="0.5" min="0.5" max="500" id="task-pts-\' + item.id + \'" data-item-id="\' + item.id + \'" data-default-pts="\' + item.points + \'" value="\' + val + \'" class="w-16 px-2 py-1 text-center font-black text-xs rounded-xl border border-slate-200 bg-white focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-200 text-[#2E2545]">\' +\n                            \'<span class="text-[10px] font-bold text-[#7E7494]">分</span>\' +\n                        \'</div>\' +\n                    \'</div>\';\n                });\n\n                html += \'</div></div>\';\n            });\n\n            container.innerHTML = html;\n            document.getElementById(\'task-points-pin\').value = \'\';\n            const errEl = document.getElementById(\'task-points-error\');\n            errEl.classList.add(\'hidden\');\n            errEl.textContent = \'\';\n            openModal(\'modal-custom-task-points\');\n        }\n\n        function resetDefaultTaskPoints() {\n            getAllConfigurableItems().forEach(item => {\n                const input = document.getElementById(\'task-pts-\' + item.id);\n                if (input) {\n                    input.value = item.points;\n                }\n            });\n            const errEl = document.getElementById(\'task-points-error\');\n            errEl.classList.remove(\'hidden\');\n            errEl.className = \'text-xs font-extrabold text-emerald-600 text-center\';\n            errEl.textContent = \'✅ 已重置为预设默认分值，请输入 PIN 码后点击“保存分值”即可生效！\';\n        }\n\n        function saveCustomTaskPoints() {\n            const pinVal = document.getElementById(\'task-points-pin\').value.trim();\n            const errEl = document.getElementById(\'task-points-error\');\n            errEl.className = \'text-xs font-extrabold text-rose-600 text-center\';\n\n            if (pinVal !== state.pin) {\n                errEl.textContent = \'❌ 请输入正确的家长 4 位 PIN 码（默认 1234）\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            const newCustomPoints = {};\n            let hasInvalid = false;\n            const allItems = getAllConfigurableItems();\n\n            for (const item of allItems) {\n                const input = document.getElementById(\'task-pts-\' + item.id);\n                if (input) {\n                    const parsed = parseFloat(input.value);\n                    if (isNaN(parsed) || parsed <= 0 || parsed > 500) {\n                        hasInvalid = true;\n                        break;\n                    }\n                    const cleanVal = Math.round(parsed * 10) / 10;\n                    if (cleanVal !== item.points) {\n                        newCustomPoints[item.id] = cleanVal;\n                    }\n                }\n            }\n\n            if (hasInvalid) {\n                errEl.textContent = \'❌ 分值必须在 0.5 到 500 之间，请检查输入\';\n                errEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            state.customTaskPoints = newCustomPoints;\n            saveState();\n            closeModal(\'modal-custom-task-points\');\n            renderAll();\n            playSound(\'success\');\n            showToast(\'🎯 任务与专属加成分值已成功更新并生效！\');\n        }\n\n        function openShareModal() {\n            document.getElementById(\'space-id-input\').value = currentSpaceId === \'default\' ? \'\' : currentSpaceId;\n            const curNameEl = document.getElementById(\'modal-current-space-name\');\n            if (curNameEl) {\n                const childDisplayName = (state.nickname && state.nickname.trim()) || \n                                         (state.studentName && state.studentName.trim() && state.studentName.trim() !== \'星光少女成长打卡站\' && state.studentName.trim() !== \'星际少年成长打卡站\' ? state.studentName.trim() : \'\') ||\n                                         (currentSpaceId === \'default\' ? \'默认个人空间\' : currentSpaceId);\n                curNameEl.textContent = childDisplayName;\n            }\n            openModal(\'modal-share\');\n        }\n\n        function switchFamilySpace() {\n            const raw = document.getElementById(\'space-id-input\').value.trim().toLowerCase();\n            const targetSpace = raw || \'default\';\n            if (!/^[a-z0-9_-]{1,24}$/.test(targetSpace)) {\n                showToast(\'⚠️ 空间暗号请使用 1-24 位字母、数字或下划线\');\n                return;\n            }\n            localStorage.setItem(\'STARLIGHT_LAST_SPACE_ID\', targetSpace);\n\n            try {\n                const url = new URL(window.location.href);\n                if (targetSpace === \'default\') {\n                    url.searchParams.delete(\'space\');\n                } else {\n                    url.searchParams.set(\'space\', targetSpace);\n                }\n                window.history.replaceState({}, \'\', url.toString());\n            } catch (e) {}\n\n            loadState();\n            closeModal(\'modal-share\');\n            renderAll();\n            const isBoy = (state.theme || \'girl\') === \'boy\';\n            const spaceEmoji = isBoy ? \'👦\' : \'👧\';\n            const childName = (state.nickname && state.nickname.trim()) || (targetSpace === \'default\' ? \'默认个人空间\' : targetSpace);\n            showToast(`${spaceEmoji} 已进入个人独立空间：「${childName}」`);\n        }\n\n        function resetTodayBoardWithPin() {\n            const oldPin = document.getElementById(\'set-old-pin\').value.trim();\n            const msgEl = document.getElementById(\'settings-msg\');\n            if (oldPin !== state.pin) {\n                msgEl.textContent = \'❌ 请先输入正确的当前家长 PIN 码\';\n                msgEl.classList.remove(\'hidden\');\n                return;\n            }\n\n            TASKS.forEach(t => {\n                state.todayChecks[t.id] = { checked: false, note: \'\' };\n            });\n            state.todaySpeedBonus = false;\n            state.todayNeatBonus = false;\n            saveState();\n            closeModal(\'modal-settings\');\n            renderAll();\n            showToast(\'🔄 今日卡片勾选已清空（如需同步冲抵今日已入账积分，请再点一次家长核算提交）\');\n        }\n\n        function exportDataJSON() {\n            const str = JSON.stringify(state, null, 2);\n            const blob = new Blob([str], { type: \'application/json\' });\n            const url = URL.createObjectURL(blob);\n            const a = document.createElement(\'a\');\n            a.href = url;\n            a.download = `星光成长打卡备份_${state.currentDateKey}.json`;\n            document.body.appendChild(a);\n            a.click();\n            document.body.removeChild(a);\n            URL.revokeObjectURL(url);\n            showToast(\'📥 备份文件已下载\');\n        }\n\n        function importDataJSON(event) {\n            const file = event.target.files[0];\n            if (!file) return;\n            const reader = new FileReader();\n            reader.onload = function(e) {\n                try {\n                    const data = JSON.parse(e.target.result);\n                    if (data && typeof data === \'object\') {\n                        const fresh = createFreshDefaultState();\n                        state = { ...fresh, ...data };\n                        normalizeAndRolloverState(state);\n                        saveState();\n                        renderAll();\n                        showToast(\'🎉 备份数据清洗并恢复成功！\');\n                    } else {\n                        showToast(\'❌ 备份文件格式不正确\');\n                    }\n                } catch (err) {\n                    showToast(\'❌ 解析备份文件失败\');\n                }\n            };\n            reader.readAsText(file);\n            event.target.value = \'\';\n        }\n\n        function switchTab(tab) {\n            [\'tasks\', \'shop\', \'history\'].forEach(t => {\n                const sec = document.getElementById(`tab-${t}`);\n                const btn = document.getElementById(`tab-btn-${t}`);\n                if (t === tab) {\n                    sec.classList.remove(\'hidden\');\n                    btn.className = \'py-2 px-3 rounded-[15px] font-extrabold text-xs sm:text-sm transition-all flex items-center justify-center gap-1.5 theme-primary-bg text-white shadow-sm\';\n                } else {\n                    sec.classList.add(\'hidden\');\n                    btn.className = \'py-2 px-3 rounded-[15px] font-extrabold text-xs sm:text-sm transition-all flex items-center justify-center gap-1.5 text-[#6E6385] hover:bg-violet-50/70\';\n                }\n            });\n        }\n\n        function openModal(id) {\n            const el = document.getElementById(id);\n            if (!el) return;\n            el.classList.remove(\'hidden\');\n            el.classList.add(\'flex\');\n            document.body.classList.add(\'overflow-hidden\');\n        }\n\n        function closeModal(id) {\n            let el = null;\n            if (typeof id === \'string\') {\n                el = document.getElementById(id);\n            } else if (id && id.nodeType) {\n                el = id.closest ? id.closest(\'[id^="modal-"]\') : id;\n            }\n            if (!el) return;\n            el.classList.add(\'hidden\');\n            el.classList.remove(\'flex\');\n            const openModals = document.querySelectorAll(\'[id^="modal-"].flex\');\n            if (openModals.length === 0) {\n                document.body.classList.remove(\'overflow-hidden\');\n            }\n        }\n\n        function showToast(msg) {\n            const container = document.getElementById(\'toast-container\');\n            const el = document.createElement(\'div\');\n            el.className = \'bg-[#2E2545]/95 text-white text-xs sm:text-sm font-extrabold px-4 py-3 rounded-2xl shadow-pastel border border-violet-300/30 animate-pop pointer-events-auto\';\n            el.textContent = msg;\n            container.appendChild(el);\n            setTimeout(() => {\n                el.style.opacity = \'0\';\n                el.style.transition = \'opacity 0.25s ease\';\n                setTimeout(() => el.remove(), 250);\n            }, 2500);\n        }\n\n        function escapeHtml(str) {\n            return String(str)\n                .replace(/&/g, \'&amp;\')\n                .replace(/</g, \'&lt;\')\n                .replace(/>/g, \'&gt;\')\n                .replace(/"/g, \'&quot;\');\n        }\n\n        const canvas = document.getElementById(\'confetti-canvas\');\n        const ctx = canvas.getContext(\'2d\');\n        let particles = [];\n        let animFrame = null;\n\n        function resizeCanvas() {\n            canvas.width = window.innerWidth;\n            canvas.height = window.innerHeight;\n        }\n        window.addEventListener(\'resize\', resizeCanvas);\n        resizeCanvas();\n\n        function fireConfetti(count) {\n            const activeTheme = previewingTheme || state.theme || \'girl\';\n            const colors = THEME_PRESETS[activeTheme]?.confettiColors || THEME_PRESETS.girl.confettiColors;\n            for (let i = 0; i < count; i++) {\n                particles.push({\n                    x: window.innerWidth * (0.2 + Math.random() * 0.6),\n                    y: window.innerHeight * 0.4,\n                    vx: (Math.random() - 0.5) * 13,\n                    vy: -Math.random() * 12 - 4,\n                    size: Math.random() * 9 + 5,\n                    color: colors[Math.floor(Math.random() * colors.length)],\n                    rot: Math.random() * 360,\n                    vRot: (Math.random() - 0.5) * 10,\n                    alpha: 1\n                });\n            }\n            if (!animFrame) loopConfetti();\n        }\n\n        function fireMicroConfetti(originX, originY) {\n            const activeTheme = previewingTheme || state.theme || \'girl\';\n            const colors = THEME_PRESETS[activeTheme]?.confettiColors || THEME_PRESETS.girl.confettiColors;\n            const x = originX || window.innerWidth / 2;\n            const y = originY || window.innerHeight / 2;\n            for (let i = 0; i < 7; i++) {\n                particles.push({\n                    x: x + (Math.random() - 0.5) * 16,\n                    y: y + (Math.random() - 0.5) * 16,\n                    vx: (Math.random() - 0.5) * 7,\n                    vy: -Math.random() * 5 - 2.5,\n                    size: Math.random() * 4 + 3.5,\n                    color: colors[Math.floor(Math.random() * colors.length)],\n                    rot: Math.random() * 360,\n                    vRot: (Math.random() - 0.5) * 14,\n                    alpha: 1\n                });\n            }\n            if (!animFrame) loopConfetti();\n        }\n\n        const numberAnimators = {};\n        function animateNumber(elementId, targetVal, duration = 300) {\n            const el = document.getElementById(elementId);\n            if (!el) return;\n            const target = Number(targetVal) || 0;\n            const currentText = el.textContent.trim();\n            const current = parseFloat(currentText) || 0;\n\n            if (current === target) return;\n\n            if (numberAnimators[elementId]) {\n                cancelAnimationFrame(numberAnimators[elementId]);\n            }\n\n            const startTime = performance.now();\n            const startVal = current;\n            const diff = target - startVal;\n\n            function step(now) {\n                const elapsed = now - startTime;\n                const progress = Math.min(1, elapsed / duration);\n                const eased = 1 - (1 - progress) * (1 - progress);\n                const currentVal = startVal + diff * eased;\n\n                const displayVal = (target % 1 === 0 && startVal % 1 === 0)\n                    ? Math.round(currentVal)\n                    : Math.round(currentVal * 10) / 10;\n\n                el.textContent = displayVal;\n\n                if (progress < 1) {\n                    numberAnimators[elementId] = requestAnimationFrame(step);\n                } else {\n                    el.textContent = target;\n                    delete numberAnimators[elementId];\n                }\n            }\n\n            numberAnimators[elementId] = requestAnimationFrame(step);\n        }\n\n        function loopConfetti() {\n            ctx.clearRect(0, 0, canvas.width, canvas.height);\n            particles.forEach(p => {\n                p.x += p.vx;\n                p.y += p.vy;\n                p.vy += 0.35;\n                p.rot += p.vRot;\n                p.alpha -= 0.012;\n\n                ctx.save();\n                ctx.globalAlpha = Math.max(0, p.alpha);\n                ctx.translate(p.x, p.y);\n                ctx.rotate((p.rot * Math.PI) / 180);\n                ctx.fillStyle = p.color;\n                ctx.beginPath();\n                ctx.roundRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.65, 3);\n                ctx.fill();\n                ctx.restore();\n            });\n\n            particles = particles.filter(p => p.alpha > 0 && p.y < canvas.height + 30);\n            if (particles.length > 0) {\n                animFrame = requestAnimationFrame(loopConfetti);\n            } else {\n                ctx.clearRect(0, 0, canvas.width, canvas.height);\n                animFrame = null;\n            }\n        }\n\n        if (\'serviceWorker\' in navigator) {\n            window.addEventListener(\'load\', function() {\n                navigator.serviceWorker.register(\'/sw.js\').catch(function(err) {\n                    console.warn(\'[PWA] Service Worker registration failed:\', err);\n                });\n            });\n        }\n\n        \n        function resetCustomTaskPointsInputsToDefault() {\n            getAllConfigurableItems().forEach(function(item) {\n                var input = document.getElementById(\'custom-pt-\' + item.id);\n                if (input) {\n                    input.value = item.points;\n                }\n            });\n            showToast(\'🔄 已填入系统推荐默认分值，点击保存即可生效\');\n        }\n\n        // 监听网络恢复事件，自动同步离线期间的打卡数据至云端\n        window.addEventListener(\'online\', function() {\n            updateCloudIndicator(\'☁️ 网络已恢复，正在同步云端...\');\n            pushStateToCloud();\n            showToast(\'🌐 网络已恢复，离线打卡数据已自动同步\');\n        });\n\n        window.addEventListener(\'offline\', function() {\n            updateCloudIndicator(\'💾 处于离线状态 (已存本地)\', false);\n            showToast(\'📶 当前处于离线状态，打卡已安全保存在本地\');\n        });\n\n        // 键盘 Enter 快捷提交支持\n        document.addEventListener(\'keydown\', function(e) {\n            if (e.key === \'Enter\') {\n                const active = document.activeElement;\n                if (!active) return;\n                if (active.id === \'parent-settle-pin\') {\n                    e.preventDefault();\n                    confirmSettle();\n                } else if (active.id === \'reward-pin-input\') {\n                    e.preventDefault();\n                    saveNewReward();\n                } else if (active.id === \'adjust-pin-input\') {\n                    e.preventDefault();\n                    confirmManualAdjust();\n                } else if (active.id === \'space-id-input\') {\n                    e.preventDefault();\n                    switchFamilySpace();\n                }\n            }\n        });\n\n        window.onload = function() {\n            loadState();\n            renderAll();\n        };\n    </script>\n</body>\n</html>';
